INSERT INTO `cities` (`id`, `name`, `flag`, `population`, `descr`) VALUES
(1, 'Москва', 'MW.png', 13000000, 'Москва — столица России, крупнейший город страны. В Российской империи Москва была первопрестольной, древней столицей, коронационным городом императоров, важнейшим торговым и религиозным центром. В СССР Москва стала столицей РСФСР и всего Советского Союза, здесь находились Кремль, правительство, ГУЛАГ, Мавзолей Ленина, а также проходили парады Победы. В Российской Федерации Москва — политический, экономический, научный и культурный центр мирового значения, город федерального значения, где работает президент, правительство и Госдума.'),
(2, 'Санкт-Петербург', 'SP.png', 5600000, 'Санкт-Петербург — бывшая столица Российской империи с 1712 по 1918 год, основанный Петром I как «окно в Европу». Здесь правили Екатерина II, Николай II, происходили дворцовые перевороты, декабристское восстание, революции 1905 и 1917 годов. В СССР город был переименован в Ленинград, стал городом-героем, выдержал 872 дня блокады во время Великой Отечественной войны, но потерял статус столицы. В РФ Санкт-Петербург — культурная столица, крупнейший порт, центр туризма, науки и судостроения, здесь проходят экономические форумы и живут более 5 миллионов человек.'),
(3, 'Варшава', 'WW.png', 1800000, 'Варшава — столица Польши, которая в составе Российской империи с 1815 по 1915 год была центром Царства Польского. Император Александр I даровал полякам конституцию, но после восстаний 1830 и 1863 годов автономия была ликвидирована, и Варшава стала рядовым губернским городом. В СССР Варшава не входила, но после Второй мировой войны оказалась в советской сфере влияния, войдя в социалистический блок ОВД и СЭВ. В современной РФ Варшава — столица независимой Польши, члена НАТО и ЕС, однако экономические и исторические связи с Россией остаются сложными, но насыщенными.'),
(4, 'Киев', 'KV.png', 3000000, 'Киев — один из древнейших городов Восточной Европы, «мать городов русских». В Российской империи Киев был крупным губернским центром Юго-Западного края, местом Киевского университета, Киево-Печерской лавры и киевского генерал-губернаторства. В СССР Киев стал столицей Украинской ССР, третьим по значению городом Союза после Москвы и Ленинграда, здесь проходили трагические события Голодомора 1932–1933 годов и немецкой оккупации 1941–1943 годов, город получил звание «город-герой». В РФ Киев — столица независимой Украины, но для России это исторический и духовный центр, где зародилось православие и государственность.'),
(5, 'Хельсинки', 'HS.png', 660000, 'Хельсинки — столица Финляндии, которая с 1809 по 1917 год входила в состав Российской империи как Великое княжество Финляндское. Александр I сделал Хельсинки столицей княжества, здесь строились православные храмы, университет, сенат, но сохранялись шведский язык и финская автономия. В СССР Хельсинки был столицей независимой Финляндии, которая воевала с СССР в 1939–1940 и 1941–1944 годах, но затем сохраняла нейтралитет и торговала с Советским Союзом. В РФ Хельсинки — столица Финляндии, члена ЕС и НАТО, но тесные экономические и культурные связи с Санкт-Петербургом и Россией сохраняются до сих пор.'),
(6, 'Таллин', 'TN.png', 450000, 'Таллин (до 1917 года — Ревель) — столица Эстонии. В Российской империи Ревель был портовым городом Эстляндской губернии, здесь базировался Балтийский флот, работал морской торговый порт и действовало остзейское дворянство с немецкими корнями. В СССР Таллин стал столицей Эстонской ССР, важным промышленным, научным и культурным центром Прибалтики, здесь проходили Олимпийские игры 1980 года (парусная регата). В РФ Таллин — столица независимой Эстонии, члена ЕС и НАТО, русскоязычное население города остаётся значительным, а исторические здания Старого города входят в список ЮНЕСКО.'),
(7, 'Рига', 'RG.png', 620000, 'Рига — столица Латвии, крупнейший город Прибалтики. В Российской империи Рига была центром Лифляндской губернии, важнейшим балтийским портом, через который шла торговля лесом, зерном и металлами, здесь жило много немцев, латышей и русских. В СССР Рига стала столицей Латвийской ССР, индустриальным гигантом (заводы ВЭФ, «Радиотехника»), а также центром прибалтийской культуры и диссидентского движения «Лесные братья». В РФ Рига — столица независимой Латвии, члена ЕС и НАТО, но для россиян это город-символ Прибалтики с красивой архитектурой югендстиля и мощным русским культурным слоем.'),
(8, 'Вильнюс', 'VS.png', 580000, 'Вильнюс (в империи — Вильна) — столица Литвы. В Российской империи после третьего раздела Речи Посполитой (1795) Вильна стала центром Литовской, а затем Виленской губернии, здесь работал Виленский университет, жили поляки, евреи, литовцы и белорусы, а город называли «Северным Иерусалимом» из-за огромной еврейской общины. В СССР Вильнюс после присоединения Литвы в 1940 году стал столицей Литовской ССР, сильно пострадал во время войны, но был восстановлен как промышленный и культурный центр, а в 1990 году Литва первой вышла из СССР. В РФ Вильнюс — столица независимой Литвы, члена ЕС и НАТО, но для России это исторический город, связанный с общим имперским и советским прошлым.'),
(9, 'Минск', 'MS.png', 2000000, 'Минск — столица Белоруссии. В Российской империи Минск был центром Минской губернии, важным торговым узлом на путях из Москвы в Варшаву и из Балтики на юг, здесь жили белорусы, поляки, евреи и русские. В СССР Минск стал столицей Белорусской ССР, город почти полностью разрушен во время войны (оккупация 1941–1944), но затем восстановлен и превращён в образцовый советский город с широкими проспектами, сталинской архитектурой и мощной промышленностью (тракторный завод МТЗ, часовой завод «Луч»). В РФ Минск — столица независимой Белоруссии, союзника России по Союзному государству, городу присвоено звание «город-герой», а для россиян это самый близкий и понятный постсоветский мегаполис.'),
(10, 'Кишинёв', 'KN.png', 650000, 'Кишинёв — столица Молдавии. В Российской империи после присоединения Бессарабии в 1812 году Кишинёв стал центром Бессарабской губернии, здесь располагалось управление края, работали православные соборы, винные погреба и процветала торговля фруктами и вином. В СССР Кишинёв стал столицей Молдавской ССР, город сильно пострадал от землетрясения 1940 года и войны 1941–1944 годов, но затем вырос как промышленный и винодельческий центр, где работали заводы по производству насосов, холодильников и измерительных приборов. В РФ Кишинёв — столица независимой Молдавии, которая колеблется между пророссийской и прозападной ориентацией, для россиян это город виноделия, русскоязычного населения и сложной политической судьбы Приднестровья.'),
(11, 'Тбилиси', 'TS.png', 1200000, 'Тбилиси — столица Грузии. В Российской империи с 1801 года (после присоединения Картли-Кахетинского царства) Тбилиси стал центром Грузинской губернии, а затем Кавказского наместничества — резиденцией царского наместника на Кавказе, здесь жили поэты, генералы, купцы, армяне, грузины, русские и азербайджанцы. В СССР Тбилиси был столицей Грузинской ССР, городом-красавцем с серными банями, старым городом и широкими советскими проспектами, здесь прошли трагические события 1956 года (расстрел демонстрации), 1978 года (защита грузинского языка) и 1989 года (разгон митинга). В РФ Тбилиси — столица независимой Грузии, которая после войны 2008 года разорвала дипломатические отношения с Россией, но для россиян это город детства, песен Высоцкого, гостеприимства и легендарного вина.'),
(12, 'Ереван', 'YN.png', 1100000, 'Ереван — столица Армении. В Российской империи Ереван был центром Эриванской губернии, небольшим персидско-армянским городом с крепостью, который вошёл в состав России по Туркманчайскому миру 1828 года. В СССР Ереван стал столицей Армянской ССР, застроенной розовым туфом по генеральному плану архитектора Таманяна, здесь работали Матенадаран, коньячный завод, завод «Армэлектромаш», а город получил звание города-героя? (нет, но был награждён орденом Ленина). В РФ Ереван — столица независимой Армении, члена ОДКБ и ЕАЭС, союзника России, но с нестабильной политической ситуацией (бархатная революция 2018 года), для россиян это символ дружбы, коньяка, абрикосов и древней христианской культуры.'),
(13, 'Баку', 'BK.png', 2300000, 'Баку — столица Азербайджана. В Российской империи после присоединения в 1806 году Баку был уездным городом, но после нефтяного бума конца XIX века превратился в крупнейший нефтяной центр мира, здесь работали Нобели и Ротшильды, бурили первые скважины и строили первый в мире нефтяной танкер. В СССР Баку стал столицей Азербайджанской ССР, главным нефтяным городом Союза, здесь производили 80% всесоюзного нефтяного оборудования, работали заводы «Бакинский рабочий», нефтяные качалки в море («Нефтяные Камни»), а также жили миллионеры и герои социалистического труда. В РФ Баку — столица независимого Азербайджана, богатейшей страны Закавказья, для россиян это город огней, ковров, шашлыка и ильменита, а также место, где снимали любимые советские фильмы.'),
(14, 'Алма-Ата', 'AA.png', 2000000, 'Алма-Ата (с 1921 по 1993 год, сейчас — Алматы) — бывшая столица Казахстана. В Российской империи на месте города было укрепление Верный, основанное в 1854 году для защиты от кокандцев, затем центр Семиреченской области. В СССР Алма-Ата стала столицей Казахской ССР (с 1929 года), городом-садом с широченными аллеями, фонтанами, яблоневыми садами, здесь работали заводы («Алма-атинский завод тяжёлого машиностроения»), вузы, театры, а также прошли декабрьские события 1986 года (разгон молодёжной демонстрации). В РФ Алма-Ата — бывшая столица независимого Казахстана (до 1997 года), крупнейший город страны, для россиян это южная столица, место съёмок «Иглы» с Цоем, город яблок, Медео и Чимбулака.'),
(15, 'Ташкент', 'TT.png', 2500000, 'Ташкент — столица Узбекистана. В Российской империи Ташкент был крупнейшим городом Туркестанского края, центром Сырдарьинской области, в 1865 году взят русскими войсками генерала Черняева, стал торговым и административным узлом между Россией и Средней Азией. В СССР Ташкент стал столицей Узбекской ССР, третьим по населению городом Союза после Москвы и Ленинграда, здесь строили авиационный завод («Ташкентский авиационный завод имени Чкалова» — ТАПОиЧ), тракторный завод, метро (первое в Средней Азии), а город сильно пострадал от землетрясения 1966 года и был отстроен заново. В РФ Ташкент — столица независимого Узбекистана, для россиян это солнечный город с огромным русскоязычным населением, базарами, пловом и ностальгией по советскому прошлому.'),
(16, 'Душанбе', 'DS.png', 850000, 'Душанбе (до 1929 года — Дюшамбе, затем Сталинабад до 1961 года) — столица Таджикистана. В Российской империи это был небольшой кишлак Дюшамбе с еженедельным базаром по понедельникам (отсюда название), входивший в Бухарский эмират, а затем в состав Ферганской области. В СССР Душанбе стал столицей Таджикской ССР, городом-садом с широкими улицами, хлопкоочистительными заводами, ГЭС и Таджикским университетом, здесь прошла гражданская война 1990-х годов. В РФ Душанбе — столица независимого Таджикистана, беднейшей страны постсоветского пространства, для россиян это город трудовых мигрантов, Памира, высоких гор и ностальгии по братским народам.'),
(17, 'Ашхабад', NULL, 1000000, 'Ашхабад (до 1919 года — Асхабад, затем Полторацк) — столица Туркменистана. В Российской империи Асхабад был центром Закаспийской области, возник как военное укрепление после покорения туркмен в 1881 году, затем стал важным узлом Закаспийской железной дороги. В СССР Ашхабад стал столицей Туркменской ССР, городом-садом с хлопком, коврами и серпантином, полностью разрушен землетрясением 1948 года (по разным данным погибло от 40 до 110 тысяч человек) и отстроен заново. В РФ Ашхабад — столица независимого Туркменистана, самого закрытого постсоветского государства, для россиян это город мраморных зданий, золотых статуй Ниязова и вечных газовых факелов.'),
(18, 'Бишкек', 'BS.png', 1100000, 'Бишкек (до 1926 года — Пишпек, затем Фрунзе до 1991 года) — столица Киргизии. В Российской империи Пишпек был кокандской крепостью, взятой русскими войсками в 1862 году, затем стал уездным городом Семиреченской области. В СССР Фрунзе стал столицей Киргизской ССР, городом-садом с широкими проспектами, фонтанами, заводами (сельхозмашиностроение, электротехника) и Академией наук. В РФ Бишкек — столица независимой Киргизии, для россиян это самый либеральный и открытый город Средней Азии с русским языком, горами, яблоневыми садами и рынком Дордой.'),
(19, 'Одесса', 'OD.png', 1000000, 'Одесса — город-порт на Чёрном море. В Российской империи Одесса была основана Екатериной II в 1794 году, стала третьим городом империи после Петербурга и Москвы, главным торговым портом на юге, центром Новороссии, где жили греки, евреи, французы, итальянцы, русские и украинцы. В СССР Одесса стала городом-героем, знаменитой Одесской киностудией, юморинами, катакомбами, партизанским движением и трагедией еврейского гетто в румынскую оккупацию (1941–1944). В РФ Одесса — крупный город независимой Украины, для россиян это символ южного порта, «жемчужины у моря», родина Бабеля, Жванецкого и Утёсова, а после 2014 года — город с трагической судьбой и разрывом культурных связей.'),
(20, 'Харьков', 'HV.png', 1400000, 'Харьков — крупный город на северо-востоке Украины. В Российской империи Харьков был центром Харьковской губернии, первым университетским городом на Левобережье, где работали Слобожанский университет, духовная семинария и торговые ярмарки. В СССР Харьков стал первой столицей Украинской ССР (1919–1934), а затем крупнейшим промышленным центром, где производили танки (завод имени Малышева), тракторы, турбины, а также прошли пять трагических боёв за город в 1941–1943 годах. В РФ Харьков — второй по величине город Украины, для россиян это «первая столица» советской Украины, родина Высоцкого, крупнейший научный и студенческий центр, а после 2022 года — зона боевых действий.'),
(21, 'Днепр', 'DP.png', 1000000, 'Днепр (до 1926 года — Екатеринослав, затем Днепропетровск до 2016 года) — город на Днепре. В Российской империи Екатеринослав был основан как третья южная столица Потемкина, центр Екатеринославской губернии, городом металлургии (Брянский завод) и торговли зерном. В СССР Днепропетровск стал крупнейшим промышленным центром, закрытым городом из-за производства ракет (завод «Южмаш»), здесь родились Брежнев, Титов и многие советские чиновники. В РФ Днепр — третий по величине город Украины, для россиян это город ракетной промышленности, длинных проспектов и Днепрогэса.'),
(22, 'Львов', NULL, 720000, 'Львов — крупный город на западе Украины. В Российской империи Львов (Лемберг) никогда не был в её составе (был австрийским, затем польским), но в 1914–1915 годах был занят русской армией. В СССР Львов вошёл в состав Украинской ССР в 1939 году после пакта Молотова-Риббентропа, стал крупным культурным центром с польским, украинским и еврейским населением, сильно пострадал во время войны (немецкая оккупация, уничтожение еврейского гетто). В РФ Львов — город независимой Украины, для россиян это самый европейский и националистический город Украины, центр галицийской культуры, львовского шоколада и кофе.'),
(23, 'Нижний Новгород', 'NN.png', 1200000, 'Нижний Новгород (с 1932 по 1990 год — Горький) — крупный город на Волге. В Российской империи Нижний Новгород был центром Нижегородской губернии, знаменит Макарьевской (затем Нижегородской) ярмаркой — крупнейшей в империи, где торговали китайским чаем, сибирским мехом и европейскими товарами. В СССР Горький стал закрытым городом из-за оборонных заводов (автомобильный завод ГАЗ, завод «Красное Сормово»), здесь родился Максим Горький, жил Сахаров в ссылке, а город был недоступен для иностранцев. В РФ Нижний Новгород — крупный промышленный и культурный центр, столица Приволжского федерального округа, город, где строят «Ё-мобили» (шутка) и проводят чемпионаты мира.'),
(24, 'Казань', 'KZ.png', 1300000, 'Казань — столица Татарстана. В Российской империи Казань была центром Казанской губернии, одним из крупнейших университетских городов (Казанский университет, где учились Ленин, Толстой, Лобачевский), а также важным исламским центром (мечеть Кул-Шариф была разрушена при взятии города Иваном Грозным в 1552 году). В СССР Казань стала столицей Татарской АССР, крупным промышленным центром (вертолётный завод, авиационный завод имени Горбунова, оптико-механический завод), а также местом строительства Казанской ГЭС. В РФ Казань — столица Республики Татарстан, один из самых богатых и благоустроенных городов России, где мирно сосуществуют православие и ислам, а также прошли Универсиада 2013 года и чемпионат мира по футболу 2018 года.'),
(25, 'Самара', 'KB.png', 1100000, 'Самара (с 1935 по 1991 год — Куйбышев) — крупный город на Волге. В Российской империи Самара была центром Самарской губернии, важным купеческим и хлеботорговым городом, где открылась первая в России публичная библиотека и родился будущий Сталин. В СССР Куйбышев стал «запасной столицей» в годы Великой Отечественной войны — сюда эвакуировали правительство, иностранные посольства, Большой театр и заводы, здесь же построили бункер Сталина (секретный объект). В РФ Самара — крупный космический и промышленный центр (ракетно-космический центр «Прогресс», НПО «Труд»), а также ворота в заповедник Самарская Лука.'),
(26, 'Уфа', 'UF.png', 1100000, 'Уфа — столица Башкортостана. В Российской империи Уфа была центром Уфимской губернии, важным транзитным пунктом на пути в Сибирь, городом мечетей, православных соборов и купеческих особняков. В СССР Уфа стала столицей Башкирской АССР, крупным промышленным центром (нефтепереработка, моторостроительный завод, завод «Уфахимпром»), а также городом, где родился Владимир Путин (по некоторым данным, спорно, но он учился в школе № 53?). В РФ Уфа — столица Республики Башкортостан, один из крупнейших нефтяных центров страны, город с широкими проспектами и стадионом «Нефтяник».'),
(27, 'Ростов-на-Дону', 'RD.png', 1100000, 'Ростов-на-Дону — крупный город на юге России. В Российской империи Ростов был центром Области Войска Донского, важнейшим портом на Дону, «южными воротами» России, городом армянских купцов, греческих торговцев и донских казаков. В СССР Ростов-на-Дону стал городом-героем (после битвы за Ростов в 1941 году), крупным промышленным центром (завод «Ростсельмаш» — комбайны, вертолётный завод), а также «воровской столицей» по версии советской милиции. В РФ Ростов-на-Дону — столица Южного федерального округа, город с миллионным населением, где находится штаб Южного военного округа и проходят ярмарки.'),
(28, 'Краснодар', 'KO.png', 1000000, 'Краснодар (до 1920 года — Екатеринодар) — столица Кубани. В Российской империи Екатеринодар был центром Кубанской области, войсковым городом черноморских казаков, перенесённых сюда Екатериной II после покорения Крыма. В СССР Краснодар стал центром Краснодарского края, крупным сельскохозяйственным и промышленным городом (заводы «Краснодарский станкостроительный», «Компрессор», чаеразвесочная фабрика), а также «воротами на Кавказ». В РФ Краснодар — быстрорастущий миллионник, неофициальная южная столица России, город с одним из лучших футбольных стадионов и самым тёплым климатом.'),
(29, 'Волгоград', 'VG.png', 1000000, 'Волгоград (до 1925 года — Царицын, до 1961 года — Сталинград) — город-герой на Волге. В Российской империи Царицын был небольшим уездным городом Саратовской губернии, известным виноделием и горчичным маслом, а также ключевым пунктом обороны красных во время Гражданской войны (оборона Царицына). В СССР Сталинград стал местом величайшей битвы Второй мировой войны (1942–1943), где советская армия окружила и уничтожила армию Паулюса, город был полностью разрушен, а после восстановлен и получил звание города-героя. В РФ Волгоград — город с Мамаевым курганом, статуей «Родина-мать зовёт!», промышленный центр, но до сих пор многие жители называют его Сталинградом.'),
(30, 'Воронеж', 'VJ.png', 1000000, 'Воронеж — крупный город в Черноземье. В Российской империи Воронеж был центром Воронежской губернии, городом, где Пётр I строил первый российский флот (Азовский поход), родиной поэта Кольцова и писателя Никитина. В СССР Воронеж стал крупным промышленным центром (авиационный завод, завод «Электросигнал», «Воронежсельмаш»), а также городом, где в годы войны проходила линия фронта, и был полностью разрушен. В РФ Воронеж — крупный научный центр (Воронежский университет), родина многих космонавтов и учёных, а также «город, где был убит Мандельштам» (нет, он умер во Владивостоке, но был в ссылке в Воронеже).'),
(31, 'Пермь', 'PM.png', 1000000, 'Пермь (с 1940 по 1957 год — Молотов) — крупный город на Урале. В Российской империи Пермь была центром Пермской губернии, важным промышленным и торговым городом на реке Каме, где добывали соль, медь и строили пароходы. В СССР Молотов стал крупнейшим индустриальным центром (авиационный завод, моторостроительное объединение, нефтепереработка), а также местом, куда эвакуировали заводы из Москвы и Ленинграда в войну. В РФ Пермь — культурная столица Урала, город с оперным театром, балетом и памятниками деревянной архитектуры, а также «Пермь — не для всех?» (шутка про лозунг Дягилевского фестиваля).'),
(32, 'Екатеринбург', 'EK.png', 1500000, 'Екатеринбург (с 1924 по 1991 год — Свердловск) — столица Урала. В Российской империи Екатеринбург был основан Петром I как город-завод, став крупнейшим центром горнодобычи и металлургии, а также местом расстрела семьи последнего российского императора Николая II в 1918 году. В СССР Свердловск стал закрытым промышленным гигантом (Уралмаш, Уралхиммаш, «Уралэлектротяжмаш»), центром оборонной промышленности, где производили танки, ракеты и артиллерию, а также «столицей ГУЛАГа» (Уральское управление лагерей). В РФ Екатеринбург — крупнейший город Урала, центр бизнеса, культуры и высшего образования, место проведения саммитов ШОС и «Ельцин-центра».'),
(33, 'Челябинск', 'CH.png', 1200000, 'Челябинск — крупный промышленный центр Урала. В Российской империи Челябинск был небольшим уездным городом Оренбургской губернии, который стал бурно расти после строительства Транссибирской магистрали и превратился в «ворота в Сибирь». В СССР Челябинск стал крупнейшим промышленным центром (Челябинский тракторный завод, металлургический комбинат, трубопрокатный завод), в годы войны здесь производили танки Т-34 и «Катюши», а город часто называли «Танкоградом». В РФ Челябинск — город с самой грязной атмосферой в России (по некоторым данным), но также родина знаменитого метеорита 2013 года, который упал в озеро Чебаркуль.'),
(34, 'Новосибирск', 'NK.png', 1600000, 'Новосибирск (до 1925 года — Ново-Николаевск) — столица Сибири. В Российской империи Ново-Николаевск возник как посёлок при строительстве железнодорожного моста через Обь и быстро стал крупнейшим торговым центром Сибири. В СССР Новосибирск вырос в миллионник, став крупнейшим научным центром (Академгородок, СО РАН), промышленным гигантом (завод «Сибсельмаш», «Электросигнал», ТЭЦ), а также городом с самым большим театром оперы и балета (здание-крепость). В РФ Новосибирск — третий по численности город России, неформальная столица Сибири, где проходят региональные саммиты и работает метро (единственное за Уралом).'),
(35, 'Омск', 'OM.png', 1100000, 'Омск — крупный город в Западной Сибири. В Российской империи Омск был центром Омской области, а затем Акмолинской области, важной военной крепостью и местом ссылки (Фёдор Достоевский служил здесь солдатом). В СССР Омск стал крупным промышленным центром (нефтеперерабатывающий завод, авиационный завод, завод «Электроточприбор»), а также «второй столицей» Белой армии во время Гражданской войны (ставка Колчака). В РФ Омск — крупный транспортный узел, город с трамваями, «омским метробусом» (недостроенное метро) и знаменитым омским Масленицей.'),
(36, 'Красноярск', 'KK.png', 1100000, 'Красноярск — крупный город в Восточной Сибири. В Российской империи Красноярск был центром Енисейской губернии, казачьим острогом, а затем местом золотодобычи и ссылки (декабристы, революционеры). В СССР Красноярск стал промышленным гигантом (Красноярский алюминиевый завод, гидроэлектростанция на Енисее, завод комбайнов), а также закрытым городом из-за оборонных предприятий (Красноярский завод «Красмаш»). В РФ Красноярск — крупнейший транспортный узел Восточной Сибири, город с часовней Параскевы Пятницы на Караульной горе, изображённой на десятирублёвой купюре.'),
(37, 'Иркутск', 'IK.png', 600000, 'Иркутск — крупный город в Восточной Сибири. В Российской империи Иркутск был центром Иркутской губернии, «столицей Восточной Сибири», важнейшим торговым узлом на пути в Китай и Монголию, а также местом ссылки декабристов (Волконский, Трубецкой). В СССР Иркутск стал промышленным центром (авиационный завод, гидроэлектростанция на Ангаре, нефтепереработка), а также «воротами» на Байкал. В РФ Иркутск — крупнейший город рядом с озером Байкал, центр науки и образования (Иркутский университет), а также место, где стоят старинные деревянные дома с кружевной резьбой.'),
(38, 'Владивосток', 'VK.png', 600000, 'Владивосток — главный порт на Дальнем Востоке. В Российской империи Владивосток был основан как военный пост, а затем крепость и коммерческий порт, «ворота в Тихий океан», конечная точка Транссиба (построен в 1916 году). В СССР Владивосток был закрытым городом из-за базирования Тихоокеанского флота, крупным рыболовным и торговым портом, а также местом, откуда уходили «красные» в Гражданскую войну (власть менялась 5 раз). В РФ Владивосток — крупнейший порт России на Тихом океане, место проведения саммита АТЭС 2012 года, мост на остров Русский и символ «русского Сан-Франциско».'),
(39, 'Хабаровск', NULL, 600000, 'Хабаровск — крупный город на Дальнем Востоке. В Российской империи Хабаровск был основан как военный пост Хабаровка, центр Приморской области, а затем столица Приамурского края. В СССР Хабаровск стал центром Дальневосточного военного округа, крупным промышленным и транспортным узлом (авиационный завод, судостроение), а также административным центром Хабаровского края. В РФ Хабаровск — второй по величине город Дальнего Востока, стоящий на Амуре, с трамваями, сталинскими зданиями и огромным музеем истории края.'),
(40, 'Калининград', 'KL.png', 490000, 'Калининград (до 1946 года — Кёнигсберг) — самый западный город России. Был столицей Восточной Пруссии (немецкий город), никогда не входил в состав Российской империи до 1945 года. В СССР Калининград стал городом-форпостом на Балтике, базой Балтийского флота, закрытым регионом с мощной оборонной промышленностью, полностью обрусев после выселения немцев. В РФ Калининград — эксклав России, «янтарная столица», город с готическими соборами, немецкими виллами и самой западной точкой страны.'),
(41, 'Тюмень', 'TE.png', 850000, 'Тюмень — первый русский город в Сибири (основан в 1586 году). В Российской империи Тюмень была центром Тюменской губернии (позже — Тобольской), важным торговым и ремесленным городом на пути в Сибирь. В СССР Тюмень стала «нефтяной столицей» после открытия месторождений Западной Сибири в 1960-х годах, здесь работали геологи, буровики, строители, а город рос как на дрожжах. В РФ Тюмень — один из самых богатых и благоустроенных городов России, центр нефтегазового комплекса, с лучшими дорогами и школами.'),
(42, 'Томск', 'TM.png', 570000, 'Томск — научный центр Сибири. В Российской империи Томск был центром Томской губернии, первым университетским городом за Уралом (Томский университет — 1880 год), местом ссылки и развития науки. В СССР Томск стал крупнейшим научным центром (Академгородок, институты СО РАН), а также городом с развитой деревянной архитектурой и «сибирскими Афинами». В РФ Томск — центр инноваций и IT, город с огромным количеством студентов, памятниками деревянному модерну и знаменитыми «Томскими» нарымскими домами.'),
(43, 'Кемерово', 'KR.png', 550000, 'Кемерово — столица Кузбасса, угольный центр России. В Российской империи на месте Кемерова было село Щеглово, затем Щегловск, который рос после открытия угольных месторождений в Кузнецкой котловине. В СССР Кемерово стал крупнейшим промышленным городом (уголь, металлургия, химия), одним из самых грязных городов СССР, но и самым богатым на шахтёрские традиции. В РФ Кемерово — город, где произошла трагедия в ТРЦ «Зимняя вишня» (2018 год), после чего были приняты новые законы о безопасности.'),
(44, 'Новокузнецк', 'NO.png', 540000, 'Новокузнецк (до 1931 года — Кузнецк, до 1932 года — Новокузнецк, затем Сталинск до 1961 года) — металлургическая столица Сибири. В Российской империи Кузнецк был небольшим уездным городом Томской губернии, известным своим острогом и кузнецкой крепостью. В СССР Сталинск стал городом гигантской металлургии (Кузнецкий металлургический комбинат — КМК, Западно-Сибирский металлургический завод), построенным трудом заключённых ГУЛАГа, и одним из самых загрязнённых городов мира. В РФ Новокузнецк — крупнейший центр чёрной металлургии, город с тяжёлым воздухом, но и с гордостью за свой труд.'),
(45, 'Барнаул', 'BL.png', 630000, 'Барнаул — столица Алтайского края. В Российской империи Барнаул был центром горнозаводского производства (сереброплавильные заводы Демидова), крупным купеческим городом на Оби. В СССР Барнаул стал крупным промышленным центром (шиноремонтный завод, моторный завод, заводы синтетического волокна и котельного оборудования), а также «воротами» на Алтай и в Горную Шорию. В РФ Барнаул — крупный транспортный узел, центр аграрного региона, с широкими проспектами и университетом.'),
(46, 'Улан-Удэ', 'UE.png', 440000, 'Улан-Удэ (до 1934 года — Верхнеудинск) — столица Бурятии. В Российской империи Верхнеудинск был важным купеческим городом на пути в Китай и Монголию, центром чайной торговли (Кяхтинский тракт). В СССР Улан-Удэ стал столицей Бурят-Монгольской АССР, промышленным центром (авиационный завод, локомотивовагоноремонтный завод), а также центром буддизма в СССР (Иволгинский дацан). В РФ Улан-Удэ — центр буддийской культуры России, город с огромной головой Ленина (самый большой бюст в мире) и бурятской кухней.'),
(47, 'Чита', 'CT.png', 350000, 'Чита — столица Забайкальского края. В Российской империи Чита была центром Забайкальской области, местом каторги и ссылки (декабристы, поляки, революционеры), а также центром золотодобычи. В СССР Чита стала крупным промышленным центром (завод горного оборудования, мясокомбинат, ГРЭС), а также «воротами» в Китай через Забайкальск. В РФ Чита — крупнейший город Забайкалья, центр военного округа, с холодной зимой и близостью к Монголии.'),
(48, 'Якутск', 'YK.png', 330000, 'Якутск — столица Якутии, самый холодный крупный город мира. В Российской империи Якутск был центром Якутской области, местом ссылки (раскольники, декабристы, народовольцы), важным перевалочным пунктом на пути в Охотское море и на Аляску. В СССР Якутск стал столицей Якутской АССР, центром алмазодобычи (мирные алмазы, кимберлитовые трубки), а также городом вечной мерзлоты и деревянных домов на сваях. В РФ Якутск — один из самых быстрорастущих городов Дальнего Востока благодаря алмазам и газу, но с экстремальным климатом (до -60°C).'),
(49, 'Магадан', 'MN.png', 92000, 'Магадан — столица Колымы. В Российской империи на месте Магадана не было ничего, лишь бухта Нагаева использовалась моряками. В СССР Магадан был построен как столица Дальстроя — главного управления лагерей ГУЛАГа (Севвостоклаг), через который прошли миллионы заключённых, добывавших золото, олово и уран. В РФ Магадан — город с трагической историей, памятником «Маска скорби» и музей ГУЛАГа, а также центр рыболовства и золотодобычи.'),
(50, 'Петропавловск-Камчатский', 'PR.png', 180000, 'Петропавловск-Камчатский — столица Камчатки. В Российской империи Петропавловск был военным портом и центром Камчатского края, прославился героической обороной от англо-французской эскадры в 1854 году (Крымская война). В СССР Петропавловск-Камчатский стал базой Тихоокеанского флота (подводные лодки), закрытым городом с рыбозаводами и вулканологами. В РФ Петропавловск-Камчатский — ворота в Долину гейзеров и вулканы Ключевской сопки, город с самым красивым видом на Авачинскую бухту.'),
(51, 'Южно-Сахалинск', 'YS.png', 200000, 'Южно-Сахалинск (до 1946 года — Тойохара) — столица Сахалина. В Российской империи Сахалин был местом каторги (Чехов «Остров Сахалин»), но Южно-Сахалинск тогда не существовал — после 1905 года остров южнее 50-й параллели отошёл Японии. В СССР после 1945 года город Тойохара был переименован в Южно-Сахалинск и стал столицей Сахалинской области, застроенной японскими домами и новыми советскими кварталами. В РФ Южно-Сахалинск — центр рыболовства и нефтегазовых проектов (Сахалин-1, Сахалин-2), с японским наследием и корейской диаспорой.'),
(52, 'Анадырь', 'AR.png', 15000, 'Анадырь — самый восточный город России, столица Чукотки. В Российской империи на месте Анадыря был Ново-Мариинский пост, основанный в 1889 году как центр Чукотского уезда. В СССР Анадырь стал центром Чукотского национального округа, посёлком с портом, оленеводством и золотодобычей. В РФ Анадырь — город-миллионер? нет, всего 15 тысяч человек, но с самым большим в мире православным храмом на вечной мерзлоте (Свято-Троицкий собор) и губернатором Абрамовичем в прошлом.'),
(53, 'Норильск', 'NSK.png', 180000, 'Норильск — промышленный гигант за полярным кругом. В Российской империи на месте Норильска ничего не было, лишь геологические экспедиции находили медь и никель. В СССР Норильск был построен силами заключённых Норильлага (Норильский исправительно-трудовой лагерь), а затем стал центром добычи никеля, меди, кобальта и палладия (Норильский никель), одним из самых загрязнённых городов мира. В РФ Норильск — закрытый город (формально открыт с 2009 года), где в 2020 году произошла крупная утечка дизельного топлива из-за просадки вечной мерзлоты.'),
(54, 'Братск', 'BT.png', 230000, 'Братск — город энергетиков на Ангаре. В Российской империи на месте Братска была деревня Братский острог, основанная в 1631 году как опорный пункт казаков. В СССР Братск стал городом-гигантом благодаря строительству Братской ГЭС (1961–1967) — одной из крупнейших в мире, а также алюминиевому заводу и лесопромышленному комплексу. В РФ Братск — город с «братским морем» (водохранилище), проблемной экологией и знаменитой песней «А я еду в Братск» (Аркадий Северный).'),
(55, 'Сургут', 'ST.png', 380000, 'Сургут — нефтяная столица Западной Сибири. В Российской империи Сургут был небольшим уездным городом Тобольской губернии, известным рыболовством и меховой торговлей. В СССР Сургут стал стремительно расти после открытия нефтяных месторождений (Самотлорское и другие) в 1960-х годах, превратившись в центр нефтедобычи (Сургутнефтегаз). В РФ Сургут — один из самых богатых городов России, с огромной ТЭЦ, нефтеперерабатывающим заводом и самым большим аэропортом региона.'),
(56, 'Нижневартовск', 'NJ.png', 280000, 'Нижневартовск — крупный нефтяной центр. В Российской империи на месте Нижневартовска не было города — лишь юрты хантов и редкие русские поселения. В СССР Нижневартовск возник как посёлок геологов в 1960-х, а после открытия Самотлорского месторождения (самое крупное в СССР) стал центром нефтедобычи. В РФ Нижневартовск — город с мостами через Обь, огромным нефтегазовым комплексом и лучшими в Югре школами (благодаря нефтяным деньгам).'),
(57, 'Ханты-Мансийск', 'HM.png', 100000, 'Ханты-Мансийск — столица ХМАО (Югры). В Российской империи на месте города было село Самарово (основано в 1637 году), центр остяцко-вогульского края. В СССР Ханты-Мансийск стал столицей национального округа, небольшим посёлком с лесозаводом и портом на Иртыше. В РФ Ханты-Мансийск превратился в современный центр нефтяного региона, где проходят международные шахматные турниры (Кубок мира) и биатлонные гонки, а также стоит необычный Археопарк с бронзовыми мамонтами.'),
(58, 'Караганда', 'KG.png', 500000, 'Караганда — крупный промышленный центр в Казахстане. В Российской империи на месте Караганды были кочевья, первые угольные залежи открыты в 1833 году, но разработка не велась. В СССР Караганда стала «шахтёрской столицей» Казахской ССР, одним из крупнейших центров угледобычи, а также местом Карлага (Карагандинский исправительно-трудовой лагерь), где погибло много заключённых. В РФ Караганда — третий по величине город Казахстана, с шахтами, металлургией и знаменитой фразой «Где-где? — В Караганде!».'),
(59, 'Шымкент', NULL, 1200000, 'Шымкент (до 1993 года — Чимкент) — крупный город на юге Казахстана. В Российской империи Шымкент был кокандской крепостью, взятой русскими войсками в 1864 году, затем стал центром Сырдарьинской области. В СССР Чимкент стал крупным промышленным центром (свинцово-цинковый завод, химический завод, хлопкоочистительный комбинат), а также центром выращивания хлопка. В РФ Шымкент — третий по численности город Казахстана, крупный культурный и экономический центр на Шёлковом пути.'),
(60, 'Астана', NULL, 1200000, 'Астана (с 1998 по 2019 год — Акмола, затем Нур-Султан, сейчас снова Астана) — столица Казахстана. В Российской империи на месте Астаны был посёлок Акмолинск, основанный в 1830 году как военное укрепление. В СССР Акмолинск стал городом, известным как «город-призрак» из-за неудачной попытки сделать его центром освоения целины (Акмолинский целинный край). В РФ Астана стала новой столицей независимого Казахстана в 1997 году, превратившись в ультрасовременный город с Байтереком, шаныраками и футуристической архитектурой.'),
(61, 'Актобе', NULL, 500000, 'Актобе (до 1999 года — Актюбинск) — крупный город на западе Казахстана. В Российской империи Актюбинск был основан как военное укрепление в 1869 году, затем стал центром Актюбинской области. В СССР Актюбинск вырос как промышленный центр (ферросплавный завод, химический комбинат), а также как железнодорожный узел. В РФ Актобе — один из крупнейших городов Казахстана, центр нефтехимии и сельского хозяйства.'),
(62, 'Ош', NULL, 300000, 'Ош — второй по величине город Кыргызстана. В Российской империи Ош был кокандской крепостью, взятой в 1876 году, затем стал уездным городом Ферганской области, важным торговым центром на Великом шёлковом пути. В СССР Ош стал крупным промышленным центром (хлопкоочистительный, текстильный, шёлкомотальный комбинаты), а также местом межэтнических столкновений в 1990 году (кыргызско-узбекский конфликт). В РФ Ош — древний город с 3000-летней историей, центр Ферганской долины, с Узгенским базаром и Сулайман-Тоо (священная гора).'),
(63, 'Худжанд', NULL, 180000, 'Худжанд (до 1936 года — Ходжент, до 1991 года — Ленинабад) — второй по величине город Таджикистана. В Российской империи Ходжент был кокандским городом, взят русскими в 1866 году, центр Ходжентского уезда Ферганской области. В СССР Ленинабад стал крупным промышленным и сельскохозяйственным центром (хлопок, шёлк, консервный завод), а также родиной многих советских партийных лидеров Таджикистана. В РФ Худжанд — центр Согдийской области, древний город на Шёлковом пути, с таджикско-узбекским населением.'),
(64, 'Мары', NULL, 150000, 'Мары (до 1937 года — Мерв) — крупный город в Туркменистане. В Российской империи Мерв был древним оазисом, взятым русскими войсками в 1884 году, центр Мервского уезда Закаспийской области. В СССР Мары стал центром Марыйской области, крупным хлопководческим и газодобывающим регионом. В РФ Мары — город с древним городищем Гяур-кала и мавзолеем султана Санджара, а также центром туркменского ковроделия.'),
(65, 'Наманган', NULL, 600000, 'Наманган — крупный город в Узбекистане. В Российской империи Наманган был кокандским городом, взят русскими в 1875 году, центр Наманганского уезда Ферганской области. В СССР Наманган стал центром хлопкоочистительной, текстильной и химической промышленности, а также местом массовых беспорядков 1989 года (межэтнические конфликты). В РФ Наманган — третий по величине город Узбекистана, центр Ферганской долины, с исламским наследием.'),
(66, 'Самарканд', NULL, 550000, 'Самарканд — древний город Узбекистана, жемчужина Шёлкового пути. В Российской империи Самарканд был взят русскими войсками в 1868 году, стал центром Зеравшанского округа, затем Самаркандской области. В СССР Самарканд стал центром Узбекской ССР до 1930 года, затем областным центром, с развитой промышленностью (хлопок, шёлк, табак), а также туристической меккой. В РФ Самарканд — город с архитектурой Тимуридов (Регистан, Гур-Эмир, Биби-Ханым), внесённый в ЮНЕСКО.'),
(67, 'Бухара', NULL, 280000, 'Бухара — древний город Узбекистана. В Российской империи Бухара была столицей Бухарского эмирата, вассального по отношению к России (с 1873 года), но сам город не входил в состав империи. В СССР Бухара стала частью Узбекской ССР, центром Бухарской области, с промышленностью (хлопкоочистительная, ковроткачество, каракулеводство). В РФ Бухара — город-музей с тысячей архитектурных памятников (крепость Арк, минарет Калян, мавзолей Саманидов).'),
(68, 'Коканд', NULL, 250000, 'Коканд — исторический город в Ферганской долине Узбекистана. В Российской империи Коканд был столицей Кокандского ханства, которое было завоёвано Россией в 1876 году, после чего город стал центром Ферганской области. В СССР Коканд стал крупным промышленным центром (химический завод, текстильная фабрика, пищевая промышленность), а также культурным центром Ферганской долины. В РФ Коканд — город с дворцом Худояр-хана, мечетями и медресе, бывшая столица ханства.'),
(117, 'Владикавказ', NULL, 300000, 'Владикавказ (с 1931 по 1944 и с 1954 по 1990 год — Орджоникидзе) — столица Северной Осетии. В Российской империи Владикавказ был основан в 1784 году как крепость на Военно-Грузинской дороге, затем стал центром Терской области. В СССР Орджоникидзе стал столицей Северо-Осетинской АССР, крупным промышленным центром (цветная металлургия, электротехника, приборостроение). В РФ Владикавказ — город с осетинской культурой, древним христианством (Аланский Успенский монастырь), а также местом трагического Беслана (2004 год) рядом с городом.'),
(118, 'Сочи', '1778127400_4087.png', 430000, 'Сочи — крупнейший курорт России на Чёрном море. В Российской империи Сочи был небольшим посёлком, вошедшим в состав России после Кавказской войны (1864), затем дачным местом для аристократии и купечества. В СССР Сочи стал всесоюзной здравницей, местом сталинских дач (дача Сталина в Хосте), санаториев, парков и знаменитого фестиваля «Кинотавр». В РФ Сочи принял зимние Олимпийские игры 2014 года, после чего стал ультрасовременным курортом с олимпийским парком, трассой «Формулы-1» и горнолыжными трассами Красной Поляны.'),
(119, 'Архангельск', NULL, 350000, 'Архангельск — важный порт на севере России. В Российской империи Архангельск был основан в 1584 году, став главным морским портом России до основания Петербурга, центром поморской культуры и лесоторговли. В СССР Архангельск стал крупнейшим лесопромышленным центром, базой Северного флота, а также местом ссылки и лагерей ГУЛАГа. В РФ Архангельск — столица Русского Севера, город деревянного зодчества (малые Карелы), морского вокзала и ледоколов.'),
(123, 'Тула', '1778127069_7718.png', 470000, 'Тула — город-герой, оружейная столица России. В Российской империи Тула была центром Тульской губернии, знаменита оружейными заводами (Тульский оружейный завод — 1712 год), пряниками и самоварами. В СССР Тула стала городом-героем (1976 год) благодаря обороне 1941 года, а также крупным центром машиностроения и оборонной промышленности. В РФ Тула — город с Тульским кремлём, музеем оружия и старыми пряничными традициями.'),
(124, 'Ижевск', NULL, 650000, 'Ижевск — столица Удмуртии, оружейный центр. В Российской империи Ижевск был основан в 1760 году как железоделательный и оружейный завод, став одним из главных арсеналов империи (Ижевский оружейный завод). В СССР Ижевск стал крупнейшим центром производства стрелкового оружия (автоматы Калашникова), а также мотоциклов (Ижмаш) и ракетной техники. В РФ Ижевск — город с оружейным музеем, прудом-водохранилищем и родиной Михаила Калашникова.'),
(136, 'Курган', 'KRG.png', 300763, 'Курган (изначально — слобода Царево Городище) — город в России, административный центр Курганской области. Основан в 1679 году крестьянином Тимофеем Невежиным. В 1782 году по указу Екатерины II получил статус города и современное название. В XIX веке был местом ссылки декабристов, оказавших влияние на культурную жизнь поселения. В советский период, особенно после образования Курганской области в 1943 году, стал крупным промышленным центром: сюда эвакуировали предприятия в годы Великой Отечественной войны. В 1971 году основан Центр травматологии и ортопедии им. академика Г. А. Илизарова, принёсший городу мировую известность. Сегодня Курган — административный, промышленный и медицинский центр Зауралья, с 2025 года носит звание «Город трудовой доблести».');

