--
-- Структура таблицы `clothes`
--

CREATE TABLE `clothes` (
  `id` int NOT NULL,
  `name` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `img` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `descr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `countries_id` int NOT NULL,
  `cities_id` int DEFAULT NULL,
  `user_id` int DEFAULT NULL,
  `moderation_status` int DEFAULT '0',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Дамп данных таблицы `clothes`
--

INSERT INTO `clothes` (`id`, `name`, `img`, `descr`, `status`, `countries_id`, `cities_id`, `user_id`, `moderation_status`, `created_at`) VALUES
(1, 'Мундир офицера лейб-гвардии Преображенского полка', 'cloth1.jpg', 'Парадный мундир офицера Преображенского полка — одного из старейших полков Русской императорской армии, основанного Петром I. Мундир тёмно-зелёного цвета с красными обшлагами, золотым шитьём и галунами. Носился с ботфортами, треуголкой и шпагой. Символ русской гвардии XVIII–XIX веков.', 'военная форма', 1, 2, NULL, 1, '2026-05-03 22:50:54'),
(2, 'Сарафан русский народный', 'cloth2.webp', 'Традиционный русский женский сарафан, распространённый в северных губерниях. Шился из парчи, шёлка или домотканого сукна. Носился с душегреей, кокошником и жемчужными украшениями. Отличался стройным силуэтом и богатством отделки.', 'народный костюм', 1, 1, NULL, 1, '2026-05-03 22:50:54'),
(4, 'Костюм архангельский народный', 'cloth4.webp', 'Традиционный женский костюм Архангельской губернии (северорусский тип). Основные элементы: глухой косоклинный сарафан из шёлка или парчи, душегрея на лямках, кокошник жемчужный, рубаха с поликами. Характерны синий, алый и золотой цвета. Отличается богатством жемчужного шитья и стройностью силуэта. Символ северной Руси.', 'народный костюм', 1, 119, NULL, 1, '2026-05-03 22:50:54'),
(6, 'Гимнастёрка обр. 1935 года', 'cloth6.jpg', 'Полевая рубаха красноармейца защитного цвета (хаки). Носилась с ремнём, галифе и сапогами. В гимнастёрке советские солдаты прошли Финскую и Великую Отечественную войны. Символ солдата-освободителя.', 'военная форма', 2, 1, NULL, 1, '2026-05-03 22:50:54'),
(9, 'Парадный мундир маршала СССР', 'cloth8.png', 'Парадная форма высшего командного состава. Цвет тёмно-синий или серо-стальной. Китель с красными кантами, золотыми погонами, орденами и маршальской звездой. Символ советской военной элиты.', 'военная форма', 2, 1, NULL, 1, '2026-05-03 22:50:54'),
(10, 'Костюм татарский народный', 'cloth10.png', 'Традиционный костюм казанских татар. Женский вариант: платье-камзол с широкими рукавами, бархатный камзол (безрукавка), фартук, головной убор калфак (бархатная шапочка) с подвесками, ичиги (сапожки) с узорами. Мужской: рубаха-туникообразная, широкие штаны, тюбетейка, бешмет (кафтан). Характерны малиновый, зелёный, золотой цвета. Символ татарского народа.', 'народный костюм', 1, 24, NULL, 1, '2026-05-03 22:50:54'),
(11, 'Косоворотка', 'cloth9.webp', 'Традиционная русская мужская рубаха с косым воротом. Носилась на выпуск, подпоясанная кушаком. Была любимой одеждой Николая II. Символ русского национального костюма.', 'народный костюм', 1, 1, NULL, 1, '2026-05-03 22:50:54'),
(12, 'Костюм башкирский народный', 'cloth12.jpg', 'Традиционный костюм башкир. Женский вариант: платье с оборками, нагрудник, камзол (безрукавка), головной убор кашмау (шапка с серебряными монетами), сапоги с узорами. Мужской: рубаха, штаны, елян (суконный халат), тюбетейка, кожаные сапоги. Характерны синий, красный, зелёный цвета с обильной серебряной отделкой. Символ башкирского народа.', 'народный костюм', 1, 26, NULL, 1, '2026-05-03 22:50:54'),
(13, 'Бушлат матроса ВМФ СССР', 'cloth11.jpg', 'Зимнее пальто матросов и старшин ВМФ. Цвет чёрный, двубортный, из плотного сукна. Носится с тельняшкой и бескозыркой. Символ суровых моряков-североморцев.', 'военная форма', 2, 2, NULL, 1, '2026-05-03 22:50:54'),
(15, 'Парадный китель офицера ВС РФ', 'cloth15.webp', 'Парадный китель офицера Вооружённых Сил Российской Федерации. Цвет защитный (сухопутные) или синий (ВКС). Китель открытый, с золотыми погонами, аксельбантом и орденскими планками. Носится с фуражкой, белой рубашкой и галстуком. Символ современной российской армии.', 'военная форма', 3, NULL, NULL, 1, '2026-05-03 22:50:54'),
(16, 'Костюм казачий донской', 'cloth16.webp', 'Традиционный костюм донских казаков. Женский вариант: юбка с кофтой (парочка), платок с кружевами, передник, черевички (туфельки). Мужской: черкеска (суконный кафтан), бешмет, шаровары с лампасами, папаха, башлык, сапоги, кинжал на поясе. Характерны чёрный, синий, красный цвета. Символ казачества и вольницы.', 'народный костюм', 1, 27, NULL, 1, '2026-05-03 22:50:54'),
(17, 'Повседневная форма ВС РФ (ВКПО)', 'cloth17.webp', 'Повседневный полевой костюм Вооружённых Сил РФ (ВКПО — всесезонный комплект полевой одежды). Цвет хаки (цифровой камуфляж ЕМР). Состоит из куртки, брюк, футболки, берцев, головного убора (кепка или панама). Используется всеми родами войск с 2010-х годов. Символ современной пехоты и мотострелков.', 'военная форма', 3, 1, NULL, 1, '2026-05-03 22:50:54'),
(18, 'Парадная форма Президентского полка', 'cloth18.webp', 'Парадная форма военнослужащих Президентского полка (Кремлёвский полк). Цвет тёмно-синий, китель с золотым шитьём, красными кантами и аксельбантом. Головной убор — фуражка с кокардой и орлом. Носится с белыми перчатками и саблей на торжественных церемониях. Символ почётного караула и кремлёвской стражи.', 'военная форма', 3, 1, NULL, 1, '2026-05-03 22:50:54'),
(19, 'Полевая форма «Ратник»', 'cloth19.webp', 'Экипировка солдата будущего «Ратник» — современный комплект боевой экипировки ВС РФ. Цвет цифровой камуфляж (ЕМР). Включает бронежилет, шлем, наколенники, налокотники, разгрузочный жилет, очки. Обеспечивает защиту и эргономику. Символ современной российской боевой экипировки.', 'военная форма', 3, 1, NULL, 1, '2026-05-03 22:50:54'),
(21, 'Народная одежда Кургана', '1778134161_1.webp', 'Костюм парня в традиционной одежде Курганской области включал рубаху прямого покроя или косоворотку с разрезом на левой стороне груди (праздничные варианты украшались вышивкой), штаны до щиколотки (позднее — более длинные, из сукна или плиса), картуз (зимой — шапку из овчины), а в качестве верхней одежды — тулуп, зипун или полушубок. Костюм девушки состоял из длинной рубахи с рукавами (из льна, конопли или фабричных тканей), сарафана (туникообразного, косоклинного или круглого покроя) либо нескольких юбок одновременно (короткой до колен, с кружевами и верхней «бумажной», на шнуровке), фартука‑запона (часто тёмного цвета, с оборками, тесьмой или вышивкой), пояса и головного убора (платка, шали или повойника), дополняясь в праздники украшениями и более дорогими тканями (сатином, шёлком, атласом).', 'Народный костюм', 1, 136, 1, 1, '2026-05-07 09:09:21');

