--
-- Структура таблицы `countries`
--

CREATE TABLE `countries` (
  `id` int NOT NULL,
  `name` varchar(100) NOT NULL,
  `flag` varchar(256) NOT NULL,
  `map` varchar(256) NOT NULL,
  `population` int NOT NULL,
  `descr` text NOT NULL,
  `date_origin` date NOT NULL,
  `date_end` date DEFAULT NULL,
  `capital_id` int DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

--
-- Дамп данных таблицы `countries`
--

INSERT INTO `countries` (`id`, `name`, `flag`, `map`, `population`, `descr`, `date_origin`, `date_end`, `capital_id`) VALUES
(1, 'Российская империя', 'RE_flag.png', 'RE.png', 175137800, 'Государство, провозглашённая Петром I в 1721 году, представляла собой абсолютную монархию, сложившуюся на основе Московского царства и простиравшуюся от Балтийского моря до Тихого океана. Это была многонациональная и многоконфессиональная держава, социальная структура которой зиждилась на сословном принципе, с доминирующей ролью дворянства и наличием крепостного права, отменённого лишь в 1861 году. Империя характеризовалась этатизмом, мощной централизованной бюрократией и доминированием государства во всех сферах жизни. Её экономика носила аграрный характер с поздним и форсированным промышленным развитием в конце XIX — начале XX века. Внешняя политика была ориентирована на территориальную экспансию, обретение статуса великой европейской и мировой державы, а также на защиту и продвижение православия и славянских интересов. Культурный ландшафт сочетал глубокие традиции православия и соборности с активным, хотя часто поверхностным, заимствованием западноевропейских моделей в элитарной культуре. Империя пала в результате системного кризиса, усугублённого участием в Первой мировой войне, и была свергнута Февральской революцией 1917 года.', '1721-10-22', '1917-03-02', 2),
(2, 'СССР', 'USSR_flag.png', 'USSR.png', 287000000, 'СССР(Союз Советских Социалистических Республик (1922–1991), образованный в 1922 году, был тоталитарным, а в поздний период — авторитарным государством, построенным на основе марксистско-ленинской идеологии и однопартийной диктатуры Коммунистической партии. Его фундаментом стала плановая экономика с полной национализацией средств производства, индустриализацией, осуществлённой за счёт беспрецедентной мобилизации ресурсов и часто сопровождавшейся огромными человеческими жертвами, и коллективизацией сельского хозяйства. Социальная структура, формально провозглашавшая равенство, на деле была иерархичной, с привилегированной партийно-хозяйственной номенклатурой. СССР позиционировал себя как альтернатива капиталистическому миру, взяв на себя миссию построения коммунизма и поддержки революционных движений по всему земному шару, что привело к Холодной войне и гонке вооружений с Западом. Культура и наука находились под строгим идеологическим контролем, хотя в определённые периоды и достигали выдающихся успехов. Это было централизованное федеративное государство, где формальное равенство союзных республик сочеталось с жёсткой властью центра. Его крах в 1991 году стал результатом накопления системных экономических проблем, идеологического кризиса, национальных движений и политики перестройки.), образованный в 1922 году, был тоталитарным, а в поздний период — авторитарным государством, построенным на основе марксистско-ленинской идеологии и однопартийной диктатуры Коммунистической партии. Его фундаментом стала плановая экономика с полной национализацией средств производства, индустриализацией, осуществлённой за счёт беспрецедентной мобилизации ресурсов и часто сопровождавшейся огромными человеческими жертвами, и коллективизацией сельского хозяйства. Социальная структура, формально провозглашавшая равенство, на деле была иерархичной, с привилегированной партийно-хозяйственной номенклатурой. СССР позиционировал себя как альтернатива капиталистическому миру, взяв на себя миссию построения коммунизма и поддержки революционных движений по всему земному шару, что привело к Холодной войне и гонке вооружений с Западом. Культура и наука находились под строгим идеологическим контролем, хотя в определённые периоды и достигали выдающихся успехов. Это было централизованное федеративное государство, где формальное равенство союзных республик сочеталось с жёсткой властью центра. Его крах в 1991 году стал результатом накопления системных экономических проблем, идеологического кризиса, национальных движений и политики перестройки.', '1922-12-30', '1991-12-26', 1),
(3, 'Российская федерация', 'RF_flag.png', 'RF.png', 146263642, 'Российская Федерация(РФ), крупнейшее по территории государство мира, образовалась в 1991 году после распада СССР как демократическое правовое государство с республиканской формой правления. Согласно Конституции, Россия является президентско-парламентской республикой, где глава государства обладает широкими полномочиями. Экономика страны совершила переход от плановой советской модели к рыночной, ключевую роль в которой играют добывающие отрасли, в первую очередь нефтегазовый сектор. В 2000-е годы был достигнут значительный экономический рост и повышение уровня жизни, сопровождавшееся укреплением государственных институтов и централизацией управления. Внешняя политика России декларирует принципы суверенитета, многополярности мира и защиты национальных интересов на международной арене. Современное российское общество сочетает традиционные ценности с процессами модернизации, а культура продолжает свои многовековые традиции в новых исторических условиях. Страна сталкивается с такими вызовами, как необходимость диверсификации экономики, развитие инфраструктуры и ответ на изменения в глобальной политической и экономической архитектуре.', '1991-12-25', NULL, 1);

