--
-- Структура таблицы `events`
--

CREATE TABLE `events` (
  `id` int NOT NULL,
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `img` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `date` date NOT NULL,
  `descr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `countries_id` int NOT NULL,
  `cities_id` int DEFAULT NULL,
  `user_id` int DEFAULT NULL,
  `moderation_status` int DEFAULT '0',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Дамп данных таблицы `events`
--

INSERT INTO `events` (`id`, `name`, `img`, `date`, `descr`, `countries_id`, `cities_id`, `user_id`, `moderation_status`, `created_at`) VALUES
(32, 'Основание Академии наук', 'event1.webp', '1724-02-08', 'Указ Петра I от 28 января (8 февраля) 1724 года учредил Академию наук и художеств — первое государственное научное учреждение России. В отличие от европейских академий, она сразу включала университет и гимназию, готовя собственные кадры. Здесь работали Ломоносов, Эйлер и Бернулли.', 1, 2, NULL, 1, '2026-05-03 22:50:53'),
(33, 'Манифест о вольности дворянства', 'event2.jpg', '1762-02-18', 'Манифест Петра III освободил дворян от обязательной 25-летней военной и гражданской службы. Это привело к расцвету усадебной культуры, росту частного предпринимательства и появлению первых заводчиков из дворян. Многие дворяне занялись наукой, коллекционированием и меценатством.', 1, 1, NULL, 1, '2026-05-03 22:50:53'),
(34, 'Отечественная война', 'event3.jpg', '1812-06-24', 'Вторжение армии Наполеона (около 600 тыс. человек) дало мощнейший импульс развитию военной промышленности. Тульские, сестрорецкие и ижевские оружейные заводы работали круглосуточно. Война также породила партизанское движение и ускорила отмену крепостного права десятилетия спустя.', 1, 1, NULL, 1, '2026-05-03 22:50:53'),
(35, 'Отмена крепостного права', 'event4.webp', '1861-03-03', 'Манифест Александра II от 19 февраля 1861 года освободил 23 миллиона помещичьих крестьян. Это высвободило колоссальные трудовые ресурсы для промышленности, вызвало рост городов и железнодорожное строительство. Реформа стала толчком для развития капитализма в России.', 1, 2, NULL, 1, '2026-05-03 22:50:53'),
(37, 'Русско-турецкая война', 'event5.jpg', '1877-04-24', 'Война за освобождение балканских славян от османского ига. Российская армия под командованием Скобелева и Гурко после тяжёлой осады взяла Плевну и вышла к Константинополю. Итогом стало освобождение Болгарии, возвращение южных территорий и значительный рост военно-промышленного комплекса.', 1, NULL, NULL, 1, '2026-05-03 22:50:53'),
(38, 'Начало строительства Транссиба', 'event6.jpg', '1891-05-19', 'Цесаревич Николай (будущий Николай II) заложил первый камень во Владивостоке. Транссибирская магистраль длиной 9288 км стала самой длинной железной дорогой мира. Строительство велось 25 лет, связало европейскую часть с Дальним Востоком, ускорило экономический рост Сибири и миграцию населения.', 1, 38, NULL, 1, '2026-05-03 22:50:53'),
(39, 'Первая всеобщая перепись населения', 'event7.png', '1897-02-09', 'Единственная всеобщая перепись Российской империи, проведённая под руководством статистика П.П. Семёнова-Тян-Шанского. Население составило 125,6 млн человек. Перепись дала точные данные о социальном составе, грамотности (только 21% грамотных), национальностях и экономике, став основой для реформ Столыпина.', 1, 2, NULL, 1, '2026-05-03 22:50:53'),
(40, 'Вступление в Первую мировую войну', 'event8.webp', '1914-08-01', 'После объявления Германией войны России 1 августа 1914 года началась мобилизация 15 млн человек. Военная промышленность выросла в 4 раза за два года, но транспортный коллапс и нехватка снарядов привели к кризису. Война стала катализатором Февральской и Октябрьской революций 1917 года.', 1, 2, NULL, 1, '2026-05-03 22:50:53'),
(41, 'Образование СССР', 'event9.webp', '1922-12-30', 'I Всесоюзный съезд Советов утвердил Договор об образовании Союза Советских Социалистических Республик в составе РСФСР, Украинской, Белорусской ССР и Закавказской федерации. Было создано единое плановое хозяйство, что позволило централизованно управлять экономикой, наукой и обороной.', 2, 1, NULL, 1, '2026-05-03 22:50:53'),
(42, 'Индустриализация', 'event10.jpg', '1928-10-01', 'Первый пятилетний план (1928–1932) запустил форсированное создание тяжёлой промышленности. Построены Магнитогорский металлургический комбинат, Уралмаш, Сталинградский и Харьковский тракторные заводы, Днепрогэс. За 10 лет СССР вышел на второе место в мире по объёму промышленного производства.', 2, NULL, NULL, 1, '2026-05-03 22:50:53'),
(43, 'Победа в Великой Отечественной войне', 'event11.jpg', '1945-05-09', 'После 1418 дней войны, 27 млн погибших и полного разорения западной части страны, 9 мая 1945 года был подписан Акт о капитуляции Германии. Советская военная техника — танк Т-34, «Катюша», штурмовик Ил-2 — доказала превосходство над немецкой. Победа укрепила статус СССР как сверхдержавы.', 2, NULL, NULL, 1, '2026-05-03 22:50:53'),
(44, 'Создание ракетно-ядерного щита', 'event12.jpg', '1949-08-29', 'Испытание первой советской атомной бомбы РДС-1 на Семипалатинском полигоне ликвидировало монополию США на ядерное оружие. В 1953 году испытана водородная бомба, а в 1957 году запущена первая межконтинентальная баллистическая ракета Р-7. Это обеспечило военный паритет на десятилетия.', 2, NULL, NULL, 1, '2026-05-03 22:50:53'),
(45, 'Запуск первого спутника', 'event13.webp', '1957-10-04', 'С космодрома Байконур ракетой Р-7 выведен на орбиту ПС-1 — первый искусственный спутник Земли массой 83,6 кг. Он проработал 92 дня, совершив 1440 оборотов вокруг Земли. Это событие открыло космическую эру человечества и нанесло огромный удар по престижу США.', 2, NULL, NULL, 1, '2026-05-03 22:50:53'),
(46, 'Полет Юрия Гагарина', 'event14.webp', '1961-04-12', '12 апреля 1961 года Юрий Гагарин на корабле «Восток-1» совершил первый в истории полёт человека в космос, продлившийся 108 минут. Он облетел Землю, доказав возможность выживания человека в космических условиях. Гагарин стал национальным героем и символом советской науки.', 2, NULL, NULL, 1, '2026-05-03 22:50:53'),
(47, 'Строительство Байкало-Амурской магистрали', 'event15.jpg', '1974-04-01', 'БАМ — железная дорога длиной 4287 км через Восточную Сибирь и Дальний Восток, проложенная в зоне вечной мерзлоты. Строительство велось 10 лет, в нём участвовало 2 млн человек, в основном комсомольцев. Магистраль дала выход к месторождениям угля, нефти и газа, разгрузив Транссиб.', 2, NULL, NULL, 1, '2026-05-03 22:50:53'),
(48, 'Олимпиада-80 в Москве', 'event16.jpg', '1980-07-19', 'XXII летние Олимпийские игры в Москве — первые в Восточной Европе. В них участвовало 80 стран (55 бойкотировали из-за Афганистана). СССР завоевал 80 золотых, 69 серебряных и 46 бронзовых медалей. Игры стали пиком международного престижа СССР и демонстрацией его технологических и спортивных достижений.', 2, 1, NULL, 1, '2026-05-03 22:50:53'),
(49, 'Начало «Перестройки»', 'event17.png', '1985-04-01', 'Курс М.С. Горбачёва на ускорение социально-экономического развития, гласность и демократизацию. Были разрешены частная деятельность и иностранные инвестиции, но экономические реформы запаздывали. Перестройка привела к распаду административной системы и в конечном счёте — к развалу СССР в 1991 году.', 2, 1, NULL, 1, '2026-05-03 22:50:53'),
(51, 'Экономический кризис 1998 года', 'event18.jpg', '1998-08-17', '17 августа 1998 года правительство объявило дефолт по ГКО, девальвацию рубля и 90-дневный мораторий на выплаты банкам. Рубль упал с 6 до 21 рубля за доллар, инфляция достигла 84%, банковская система рухнула. Парадоксально, но дефолт дал стимул импортозамещению и росту внутреннего производства.', 3, NULL, NULL, 1, '2026-05-03 22:50:53'),
(53, 'Присоединение Крыма', 'event19.webp', '2014-03-18', 'После смены власти на Украине и референдума 16 марта 2014 года, 18 марта был подписан договор о принятии Крыма и Севастополя в состав РФ. За этим последовали жёсткие западные санкции, которые запустили программу полного импортозамещения в ВПК, микроэлектронике и станкостроении.', 3, 1, NULL, 1, '2026-05-03 22:50:53'),
(55, 'Программа «Цифровая экономика»', 'event20.png', '2017-07-01', 'Государственная программа с бюджетом более 200 млрд рублей направлена на создание ИТ-инфраструктуры, развитие искусственного интеллекта, квантовых технологий и кибербезопасности. В её рамках построены центры обработки данных, внедрена биометрия и запущены технопарки в 15 городах.', 3, 1, NULL, 1, '2026-05-03 22:50:53'),
(57, 'Расширение БРИКС', 'event21.jpg', '2024-01-01', 'С 1 января 2024 года к БРИКС присоединились Египет, Иран, ОАЭ, Саудовская Аравия и Эфиопия. Блок охватил около 45% населения мира и 35% мирового ВВП. Для России это открыло новые технологические каналы с Азией и Ближним Востоком в обход западных санкций.', 3, 1, NULL, 1, '2026-05-03 22:50:53'),
(58, 'Разработка вакцины «Спутник V»', 'event22.jpg', '2020-08-11', '11 августа 2020 года Россия зарегистрировала первую в мире вакцину от COVID-19 на основе аденовирусного вектора (центр Гамалеи). Позже её эффективность подтвердили исследования в 70 странах (более 92%). Вакцина стала одним из главных российских экспортных продуктов в 2020–2022 годах.', 3, 1, NULL, 1, '2026-05-03 22:50:53'),
(59, 'Атомные ледоколы нового поколения', 'event23.webp', '2020-10-21', 'Головной атомный ледокол проекта 22220 «Арктика» (самый мощный в мире — 60 МВт на валах) вошёл в строй в 2020 году. Позже добавлены «Сибирь» и «Урал». Эти ледоколы обеспечивают круглогодичную навигацию по Северному морскому пути, сокращая путь из Азии в Европу на 40% по сравнению с Суэцким каналом.', 3, 2, NULL, 1, '2026-05-03 22:50:53'),
(60, 'Возобновление лунной программы', 'event24.jpg', '2023-08-11', 'Запуск автоматической станции «Луна-25» — первой отечественной станции к Луне с 1976 года. Хотя станция разбилась при посадке, программа продолжается: в 2026–2028 годах планируются «Луна-26» (орбитальная) и «Луна-27» (посадочная с бурением). Россия вернулась в глобальную лунную гонку.', 3, NULL, NULL, 1, '2026-05-03 22:50:53'),
(61, 'Ссылка декабристов', '1778132302_1.jpg', '1830-01-01', 'С середины XVIII века в Курган массово ссылают осуждённых по политическим и уголовным статьям. Среди известных ссыльных — декабристы (Иван Повало-Швейковский, Иван Фохт и другие), участники Польского восстания, народники. В городе сохранился дом-музей декабристов.', 1, 136, 1, 1, '2026-05-07 08:38:22'),
(62, 'Пришествие советской власти', NULL, '1917-11-19', '19 ноября 1917 года Совет постановил взять в свои руки всю власть в Кургане и уезде. 17 декабря 1917 года установление Советской власти было официально провозглашено. В течении двух лет в Кургане окончательно установилась советская власть.', 2, 136, 1, 1, '2026-05-07 08:43:55'),
(63, 'Присвоение почётного звания «Город трудовой доблести»', NULL, '2025-01-15', '15 января 2025 года Указом Президента России Владимира Путина Кургану было присвоено почётное звание «Город трудовой доблести». Это решение было принято в год 80-летия Победы в Великой Отечественной войне 1941–1945 годов. Звание присвоено за значительный вклад жителей города в достижение Победы, обеспечение бесперебойного производства военной и гражданской продукции на промышленных предприятиях, а также за проявленные массовый трудовой героизм и самоотверженность.', 3, 136, 1, 1, '2026-05-07 08:47:03');

