--
-- Структура таблицы `monuments`
--

CREATE TABLE `monuments` (
  `id` int NOT NULL,
  `name` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `img` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `descr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `countries_id` int NOT NULL,
  `cities_id` int DEFAULT NULL,
  `user_id` int DEFAULT NULL,
  `moderation_status` int DEFAULT '0',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Дамп данных таблицы `monuments`
--

INSERT INTO `monuments` (`id`, `name`, `img`, `status`, `descr`, `countries_id`, `cities_id`, `user_id`, `moderation_status`, `created_at`) VALUES
(1, 'Медный всадник', 'monument1.jpg', 'памятник', 'Памятник Петру I на Сенатской площади в Санкт-Петербурге. Открыт в 1782 году по указу Екатерины II. Скульптор Этьен Фальконе изобразил царя-реформатора на вздыбленном коне, попирающем змею (символ побеждённых врагов и препятствий). Название «Медный всадник» дал А.С. Пушкин в одноимённой поэме, хотя памятник выполнен из бронзы. Громадный гранитный камень-постамент («Гром-камень») весит 1600 тонн и был доставлен из окрестностей посёлка Лахта. Монумент стал символом Санкт-Петербурга и одним из главных памятников Российской империи. Во время блокады Ленинграда его не демонтировали, а обложили брёвнами и мешками с песком. На постаменте выбита надпись на русском и латыни: «Петру Первому — Екатерина Вторая, 1782».', 1, 2, NULL, 1, '2026-05-03 22:50:54'),
(3, 'Памятник Минину и Пожарскому', 'monument2.jpg', 'памятник', 'Скульптурная группа на Красной площади в Москве, посвящённая предводителям Второго народного ополчения 1612 года — Кузьме Минину и князю Дмитрию Пожарскому. Открыт в 1818 году, автор — скульптор Иван Мартос. Это первый в Москве памятник не царю и не полководцу, а народным героям. Минин (слева) указывает рукой на Кремль, вручая меч Пожарскому, который садится на щит. Изначально стоял напротив Спасской башни, в 1931 году перенесён к Покровскому собору (храму Василия Блаженного). Бронза отливалась в Петербурге, доставлялась в Москву по воде. Постамент из красного гранита. Надпись: «Гражданину Минину и князю Пожарскому благодарная Россия. Лета 1818».', 1, 1, NULL, 1, '2026-05-03 22:50:54'),
(4, 'Памятник Екатерине II', 'monument3.jpg', 'памятник', 'Памятник императрице Екатерине Великой на площади Островского в Санкт-Петербурге (перед Александринским театром). Открыт в 1873 году по проекту скульптора Михаила Микешина. Императрица изображена в мантии, со скипетром и лавровым венком. У подножия — 9 фигур выдающихся деятелей её эпохи: Г.А. Потёмкин, А.В. Суворов, Г.Р. Державин, Е.Р. Дашкова, В.Я. Чичагов, А.Г. Орлов, И.И. Бецкой, А.А. Безбородко, М.В. Ломоносов (хотя Ломоносов умер до её правления, но символизирует науку). Высота монумента — 10,7 м. Во время блокады памятник не укрывали, он оставался на месте и не пострадал. Символ «золотого века» Российской империи.', 1, 2, NULL, 1, '2026-05-03 22:50:54'),
(5, 'Рабочий и колхозница', 'monument4.jpg', 'скульптура', 'Знаменитая скульптурная группа Веры Мухиной, созданная для советского павильона на Всемирной выставке 1937 года в Париже. Молодой рабочий и колхозница поднимают над головой серп и молот — главную эмблему СССР. Высота — 24,5 м (вместе с постаментом — 58 м). Выполнена из нержавеющей хромоникелевой стали. После выставки установлена у северного входа на ВДНХ в Москве. В 2003–2009 годах прошла реставрация. Стала символом советского искусства социалистического реализма и кинокомпании «Мосфильм» (заставка в начале фильмов). Символ мощи советского народа и единства рабочего класса и крестьянства.', 2, 1, NULL, 1, '2026-05-03 22:50:54'),
(6, 'Родина-мать зовёт!', 'monument5.jpg', 'скульптура', 'Главный монумент ансамбля «Героям Сталинградской битвы» на Мамаевом кургане в Волгограде. Скульптор — Евгений Вучетич, инженер — Николай Никитин. Открыт в 1967 году. Высота — 85 м (вместе с мечом — 87 м), вес — 8000 тонн. Женщина с поднятым мечом призывает сыновей на борьбу с врагом. На момент создания — самая высокая статуя в мире. Меч длиной 33 м весит 14 тонн, сделан из нержавеющей стали. Фигура полая внутри, толщина стенок — 25–30 см. В основание заложена капсула с землёй защитников Сталинграда. В 2022 году статуе присвоено звание «Символ воинской славы России». Главный памятник Великой Отечественной войны.', 2, 29, NULL, 1, '2026-05-03 22:50:54'),
(7, 'Памятник Юрию Гагарину', 'monument6.jpg', 'памятник', 'Монумент первому космонавту на Ленинском проспекте в Москве (площадь Гагарина). Открыт в 1980 году к Олимпийским играм. Скульптор — Павел Бондаренко, архитекторы — Яков Белопольский и Ф.М. Гажевский. Высота памятника вместе с постаментом — 42,5 м, самого космонавта — 14 м. Гагарин изображён в скафандре с распростёртыми руками, стоящим на высоком ребристом постаменте, символизирующем шлейф ракеты. Постамент выполнен из титана (такого же металла, как обшивка космического корабля «Восток-1»). У подножия — копия спускаемого аппарата. Символ советской космической эры и прорыва человечества в космос.', 2, 1, NULL, 1, '2026-05-03 22:50:54'),
(8, 'Монумент «Покорителям космоса»', 'monument7.webp', 'монумент', 'Гигантский обелиск на ВДНХ в Москве, посвящённый достижениям советской космонавтики. Открыт в 1964 году. Архитекторы — Михаил Барщ, Александр Колчин, скульптор — Андрей Файдыш-Крандиевский. Высота — 107 м (до кончика ракеты). Форма — взлетающая ракета, оставляющая за собой титановый шлейф. В основании — музей космонавтики (открыт в 1981 году, обновлён в 2009-м). На постаменте барельефы с портретами Королёва, Циолковского, Гагарина, Титова, Леонова и других. У подножия — памятник Константину Циолковскому. Символ советской науки и космической экспансии. В 2021 году рядом открыт памятник первому спутнику.', 2, 1, NULL, 1, '2026-05-03 22:50:54'),
(10, 'Памятник Ленину', 'monument8.jpg', 'памятник', 'Знаменитый памятник Владимиру Ленину на площади Ленина в Санкт-Петербурге, у Финляндского вокзала. Открыт в 1926 году (первый крупный памятник Ленину в СССР). Скульптор — Сергей Евсеев, архитекторы — Владимир Щуко, Владимир Гельфрейх. Ленин изображён выступающим с броневика (историческое событие — приезд Ленина из эмиграции в апреле 1917 года и речь с броневика у Финляндского вокзала). Броневик стилизован, фигура Ленина — динамичная, с вытянутой рукой. Высота — 10 м. Стал одним из самых тиражируемых образов Ленина в искусстве. В 2000-х годах неоднократно предлагался к сносу, но остаётся. Памятник эпохи конструктивизма и символ Октябрьской революции.', 2, 2, NULL, 1, '2026-05-03 22:50:54'),
(12, 'Картина «Битва челюскинцев» ', 'monument9.webp', 'картина', 'Картина художника Петра Малькова «Спасение челюскинцев» (1935), посвящённая эпопее спасения экипажа парохода «Челюскин», раздавленного льдами в Чукотском море в 1934 году. Лётчики-герои (Ляпидевский, Леваневский, Молоков, Каманин, Слепнёв, Водопьянов, Доронин) стали первыми Героями Советского Союза. На картине изображена эвакуация людей с дрейфующей льдины на самолёте АНТ-4. Символ советского героизма и освоения Арктики. Картина экспонируется в Центральном музее Вооружённых Сил в Москве.', 2, 1, NULL, 1, '2026-05-03 22:50:54'),
(14, 'Памятник князю Владимиру', 'monument10.jpg', 'памятник', 'Памятник крестителю Руси князю Владимиру на Боровицкой площади в Москве (у Кремля). Открыт в 2016 году (первый памятник Владимиру в столице). Скульптор — Салават Щербаков, архитектор — Игорь Воскресенский. Высота — 17,5 м (скульптура — 10 м, постамент — 7,5 м). Князь изображён с крестом в правой руке и мечом в левой (символ веры и защиты Отечества). Памятник вызвал споры: часть общества считала, что меч не нужен, но автор настоял. Бронза, гранитный постамент. Открытие приурочено к 1000-летию преставления князя (1015–2015, с опозданием). Символ выбора православной веры и единства Руси.', 3, 1, NULL, 1, '2026-05-03 22:50:54'),
(15, 'Мемориал «Защитникам советского Заполярья»', 'monument11.jpg', 'мемориал', 'Монумент защитникам Заполярья на сопке Зелёный Мыс в Мурманске, открыт в 1974 году. Скульптор — Исаак Бродский, архитекторы — Игорь Покровский, Юрий Козлов. Фигура солдата в плащ-палатке с автоматом через плечо, взгляд обращён на запад (в сторону границы). Высота — 35,5 м (солдат — 23,5 м, постамент — 12 м). Внутри памятника — зал памяти с мозаикой и списками погибших. Рядом — вечный огонь и гранитные кубы с надписями о героях. В основании заложены капсулы с землёй городов-героев. «Алёша» виден из любой точки Мурманска, стал символом стойкости северян в годы войны.', 2, NULL, NULL, 1, '2026-05-03 22:50:54'),
(16, 'Памятник «Героям Плевны»', 'monument12.webp', 'памятник', 'Часовня-памятник героям битвы под Плевной (1877) в русско-турецкой войне. Расположена в Ильинском сквере в Москве (у Китай-города). Открыта в 1887 году. Архитектор — Владимир Шервуд. Часовня выполнена в русском стиле: восьмигранная башня из чугуна, высота — 8,5 м. На гранях — иконы, барельефы, надписи о погибших офицерах и солдатах. Внутри — икона Александра Невского. Часовня построена на добровольные пожертвования в память о 200 000 русских воинов. Ежегодно 1 марта (день взятия Плевны) служат панихиду. Символ русско-турецкой войны и освобождения Болгарии.', 1, 1, NULL, 1, '2026-05-03 22:50:54'),
(17, 'Памятник «Бронзовый солдат»', 'monument13.webp', 'памятник', 'Монумент Воину-освободителю в Таллине (Эстония), установленный в 1947 году на холме Тынисмяги. Скульптор — Энн Роос, архитектор — Арнольд Алас. Фигура солдата в шинели с опущенной головой, на постаменте — горельеф «22 сентября 1944 года» (день освобождения Таллина). Первоначально стоял у входа в Военный музей. В 2007 году перенесён на военное кладбище, вызвав массовые протесты русскоязычного населения и «бронзовую ночь» (апрель 2007). Стал символом противостояния России и Эстонии в вопросах истории Второй мировой войны. Для россиян — символ памяти о павших воинах.', 2, 6, NULL, 1, '2026-05-03 22:50:54'),
(19, 'Мемориал «Вечный огонь» ', 'monument14.jpg', 'мемориал', 'Мемориал павшим в Великой Отечественной войне в Александровском саду Москвы. Открыт в 1967 году (архитекторы — Дмитрий Бурдин, Владимир Климова). Вечный огонь зажжён от пламени на Марсовом поле в Ленинграде. На гранитной плите — надпись: «Имя твоё неизвестно, подвиг твой бессмертен». Слева — барельеф с изображением шлема и лавровой ветви. В 1997 году установлен пост почётного караула (смена каждый час). Могила Неизвестного солдата — главный военный мемориал России. Символ памяти всех погибших в Великой Отечественной.', 3, 1, NULL, 1, '2026-05-03 22:50:54'),
(20, 'Памятник «Дружба народов»', 'monument15.webp', 'памятник', 'Фонтан «Дружба народов» на ВДНХ в Москве (построен в 1954 году). Архитекторы — Константин Топуридзе, Георгий Константиновский. Фонтан представляет собой 16 женских фигур в национальных костюмах (по числу союзных республик СССР). Фигуры из позолоты (бронза, покрытая сусальным золотом). Центральный сноп из колосьев пшеницы и подсолнухов. Вода бьёт на высоту до 24 метров. Диаметр чаши фонтана — 85 метров. Стал символом единства и братства советских народов. Один из самых узнаваемых символов ВДНХ и советской эпохи.', 2, 1, NULL, 1, '2026-05-03 22:50:54'),
(22, 'Памятник Тимофею Невежину', '656x373_1_13909fa28c5d8fc793f9c561a12f3d4b@2560x1452_0x1DUo409P_4520978308724187179.jpg.webp', 'Памятник', 'Монумент, посвящённый основателю города Кургана. Он установлен на площади имени В. М. Слосмана в Кургане. Открытие состоялось 24 августа 2017 года в канун празднования Дня города.', 3, 136, 1, 1, '2026-05-07 08:50:27'),
(23, 'Памятник Леониду Красину', '1778133393_1.jpg', 'Монумент', 'В городе Кургане установлен памятник советскому политическому деятелю, уроженцу города Л. Б. Красину (1870–1926). Это объект культурного наследия регионального значения.', 2, 136, 1, 1, '2026-05-07 08:56:33'),
(24, 'картина \"Курган\"', '1778133707_1.webp', 'Картина', 'Работа народного художника России Германа Алексеевича Травникова. Это пейзаж, на котором изображён курган, возвышающийся над вспаханным полем, а вдали, за насыпью, — город Курган. ', 2, 136, 1, 1, '2026-05-07 09:01:47');

