--
-- Структура таблицы `openings`
--

CREATE TABLE `openings` (
  `id` int NOT NULL,
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `img` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `date` date NOT NULL,
  `descr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `countries_id` int NOT NULL,
  `cities_id` int NOT NULL,
  `user_id` int DEFAULT NULL,
  `moderation_status` int DEFAULT '0',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Дамп данных таблицы `openings`
--

INSERT INTO `openings` (`id`, `name`, `img`, `date`, `descr`, `countries_id`, `cities_id`, `user_id`, `moderation_status`, `created_at`) VALUES
(1, 'Закон сохранения массы в химических реакциях', NULL, '1756-01-01', 'М.В. Ломоносов в письме к Леонарду Эйлеру сформулировал закон сохранения массы веществ при химических превращениях. Экспериментально подтвердил его, обжигая металлы в запаянных сосудах. Это один из фундаментальных законов естествознания, лежащий в основе всей современной химии и термодинамики.', 1, 2, NULL, 1, '2026-05-03 22:50:54'),
(2, 'Периодический закон химических элементов', 'open2.webp', '1869-03-01', 'Д.И. Менделеев 1 марта 1869 года составил первую таблицу, в которой элементы расположены по возрастанию атомной массы и повторению свойств. Закон предсказал существование трёх неизвестных тогда элементов (галлия, германия, скандия), открытых позже. Это основа всей современной химии и материаловедения.', 1, 2, NULL, 1, '2026-05-03 22:50:54'),
(6, 'Основы аэродинамики Н.Е. Жуковского', 'open3.png', '1904-01-01', 'Николай Жуковский, «отец русской авиации», создал теорию подъёмной силы крыла, вихревую теорию винта и метод расчёта аэродинамических сил. В 1904 году основал первый в Европе аэродинамический институт в Кашине. Без его работ невозможны были бы полёты тяжелее воздуха.', 1, 1, NULL, 1, '2026-05-03 22:50:54'),
(7, 'Трёхфазная система электроснабжения', 'open4.jpg', '1889-01-01', 'Михаил Доливо-Добровольский (русский инженер, работавший в Германии) изобрёл трёхфазный асинхронный двигатель и трёхфазный трансформатор (1889 год). Эта система используется во всём мире до сих пор для передачи электроэнергии на дальние расстояния с минимальными потерями.', 1, 2, NULL, 1, '2026-05-03 22:50:54'),
(8, 'Радиоприёмник А.С. Попова', 'open5.webp', '1895-05-07', '7 мая 1895 года А.С. Попов продемонстрировал прибор для регистрации электромагнитных волн — первый радиоприёмник. В 1896 году он передал первую в мире радиограмму на расстояние 250 метров. День радио 7 мая отмечается в России как профессиональный праздник.', 1, 2, NULL, 1, '2026-05-03 22:50:54'),
(10, 'Биосферная концепция В.И. Вернадского', NULL, '1916-01-01', 'Владимир Вернадский в работе «Биосфера» (1926, но идеи сформировались в 1916 году) определил биосферу как глобальную экосистему, преобразованную деятельностью живых организмов. Ввёл понятие ноосферы — сферы разума. Эти идеи стали основой современной экологии и глобалистики.', 1, 1, NULL, 1, '2026-05-03 22:50:54'),
(12, 'Установка «Токамак»', 'open7.jpg', '1954-01-01', 'И.Е. Тамм и А.Д. Сахаров предложили концепцию токамака (тороидальная камера с магнитными катушками). Первая установка Т-1 заработала в 1954 году в Курчатовском институте. Это устройство для магнитного удержания плазмы — главный кандидат на роль термоядерного реактора будущего (ITER).', 2, 1, NULL, 1, '2026-05-03 22:50:54'),
(14, 'Лазерная физика', 'open8.png', '1954-01-01', 'Н.Г. Басов и А.М. Прохоров создали первый мазер (квантовый генератор микроволн) в 1954 году, а затем заложили основы лазерной физики. В 1964 году они получили Нобелевскую премию вместе с Чарльзом Таунсом. Их работы привели к созданию лазеров всех типов — от хирургических до волоконных.', 2, 1, NULL, 1, '2026-05-03 22:50:54'),
(15, 'Первый видеомагнитофон', NULL, '1932-01-01', 'В 1932 году советский изобретатель К. Л. Исупов предложил использовать для записи изображения на магнитную ленту магнитные головки, закреплённые на вращающемся барабане. Однако его идеи не получили дальнейшего развития в СССР, и он передал свои разработки в Германию.', 2, 2, NULL, 1, '2026-05-03 22:50:54'),
(17, 'Аппарат искусственного кровообращения', 'open10.jpg', '1926-01-01', 'Сергей Брюхоненко в 1926 году создал автожектор — первый в мире аппарат искусственного кровообращения (прообраз АИК). Он поддерживал жизнь изолированной головы собаки (эксперимент 1928 года), доказав возможность замены сердца насосом. Это открыло эру кардиохирургии и пересадки органов.', 2, 1, NULL, 1, '2026-05-03 22:50:54'),
(18, 'Микроволновая печь в СССР', 'open11.jpg', '1941-01-01', 'Во ВНИИ мясной промышленности в 1941 году (до войны) проводились эксперименты по размораживанию мяса с помощью электромагнитных волн СВЧ-диапазона. Разработка была засекречена и не доведена до серии, но СССР имел один из первых рабочих прототипов СВЧ-печи.', 2, 1, NULL, 1, '2026-05-03 22:50:54'),
(19, 'Квантовая электроника', 'open12.png', '1954-01-01', 'Басов и Прохоров создали первый молекулярный генератор на пучке молекул аммиака в 1954 году. Это был первый квантовый усилитель, работавший на принципе индуцированного излучения. За разработку они получили Ленинскую премию в 1959 году, а затем — Нобелевскую в 1964.', 2, 1, NULL, 1, '2026-05-03 22:50:54'),
(20, 'Теория альфа-распада Г.А. Гамова', 'open13.webp', '1928-01-01', 'Георгий Гамов (работал в СССР до эмиграции) в 1928 году создал квантовую теорию альфа-распада, объяснив, как альфа-частица проходит сквозь потенциальный барьер ядра за счёт туннельного эффекта. Эта теория стала классической и легла в основу ядерной физики.', 2, 2, NULL, 1, '2026-05-03 22:50:54'),
(21, '50-кубитный ионный квантовый компьютер', 'open14.jpg', '2025-01-01', 'Физический институт имени Лебедева (ФИАН) создал 50-кубитный квантовый процессор на холодных ионах иттербия-171. Это одна из самых мощных квантовых систем в России, позволяющая выполнять алгоритмы факторизации и симуляции молекул. Разработка ведётся в рамках дорожной карты «Квантовые вычисления».', 3, 1, NULL, 1, '2026-05-03 22:50:54'),
(22, 'Система выявления дипфейков «Сипуха»', NULL, '2024-01-01', 'Алгоритм на основе свёрточных нейросетей, обученный на 2 млн аудиосэмплов, определяет поддельные аудиозаписи с точностью 99,2%. Анализирует артефакты сжатия и спектрограммы, невидимые человеческим ухом. Используется для верификации голосовых улик в МВД и антифрод-системах банков.', 3, 2, NULL, 1, '2026-05-03 22:50:54'),
(23, 'Жаропрочные композиты для двигателей', NULL, '2024-01-01', 'ВИАМ (Всероссийский институт авиационных материалов) создал керамический композит на основе карбида кремния и циркония, работающий при температуре 1600°C без активного охлаждения. Это позволяет поднять температуру в турбине авиадвигателей ПД-35 и НК-32 на 200°C, повысив КПД на 8–10%.', 3, 1, NULL, 1, '2026-05-03 22:50:54'),
(24, 'Бионический протез стопы с микропроцессором', 'open15.webp', '2025-01-01', 'Компания «Моторика» разработала первый российский влагозащищённый бионический протез стопы с микропроцессорным управлением (IP67). Адаптируется под скорость ходьбы и тип поверхности, имитируя естественную походку. Прошёл клинические испытания в 2025 году и запущен в серию.', 3, 2, NULL, 1, '2026-05-03 22:50:54'),
(26, 'Новые сорта пшеницы без ГМО', 'open16.webp', '2018-01-01', 'ВНИИ зерновых культур имени Лукьяненко вывел сорта озимой пшеницы («Алексеич», «Таня», «Юка») с урожайностью до 120 ц/га (втрое выше средней по СССР). Достигнуто это классической селекцией с использованием маркерной ДНК-диагностики, без трансгенных модификаций.', 3, 28, NULL, 1, '2026-05-03 22:50:54'),
(27, 'Терагерцовые источники для медицины', 'open17.png', '2023-01-01', 'Институт физики микроструктур РАН (Нижний Новгород) создал компактные генераторы терагерцового излучения на основе лавинно-пролётных диодов. Частоты 1–3 ТГц проникают сквозь одежду и биоткани на 1–2 мм без ионизирующего излучения, позволяя диагностировать рак кожи и кариес на ранней стадии.', 3, 23, NULL, 1, '2026-05-03 22:50:54'),
(28, 'Автономный ИИ для дронов ZALA', 'open18.webp', '2025-01-01', 'Компания ZALA AERO (входит в концерн «Калашников») создала нейросеть для автономного распознавания целей по бортовой камере. Дрон сам классифицирует объекты (танк, БМП, РСЗО), выбирает приоритет и наводится без связи с оператором — неуязвим для средств РЭБ. Применён в зоне СВО с 2025 года.', 3, 124, NULL, 1, '2026-05-03 22:50:54'),
(30, 'Квантовый генератор случайных чисел', 'open19.webp', '2024-01-01', 'Университет ИТМО разработал чип размером 1×1 мм, генерирующий истинно случайные числа на основе квантовых флуктуаций вакуума (скорость — 1 Гбит/с). Применён в системах криптозащиты банковских транзакций и государственных коммуникаций (2024), заменив программные ГСЧ, уязвимые для взлома.', 3, 2, NULL, 1, '2026-05-03 22:50:54'),
(31, 'Нахождение Святилища Савин', '1778131554_1.jpg', '1982-01-01', 'Возвышенность, высотой около 2 м от уровня воды реки Тобол, шириной 60 метров и длиной 350 метров во время весеннего наводнения бывает полностью окружена водой. С возвышенности хорошо просматривается окружающая местность. Расположена в 1,5 км к северо-востоку от села Бузан Белозерского муниципального округа Курганской области Российской Федерации. Название Савин, данное археологами объекту, в переводе с угорского[прояснить] означает «город на водяной глади»[2] или «холм среди болот»', 2, 136, 1, 1, '2026-05-07 08:25:54'),
(32, 'Изобретение кухонного очага', NULL, '1909-01-01', 'В рамках проекта «Коллекция „Царские привилегии России: Сибирь, Урал и Дальний Восток“» это изобретение было выявлено среди других технических решений дореволюционного периода. Проект направлен на изучение научно-технических достижений того времени в указанных регионах. Информация о деталях конструкции или принципах работы кухонного очага П. Серебренникова в доступных источниках не сохранилась. Известно, что в дореволюционной России подобные изобретения должны были обладать существенной новизной и иметь промышленный характер, чтобы получить охранный документ.', 1, 136, 1, 1, '2026-05-07 08:31:49'),
(33, 'Приоритет-2030', '1778132045_1.png', '2025-01-01', 'В 2025 году КГУ стал участником программы «Приоритет-2030» в статусе кандидата и вошёл в состав Научных центров мирового уровня (НЦМУ) по селекции сельскохозяйственных растений. В рамках этого проекта вуз занимается испытанием новых сортов овощных культур в климатических условиях Зауралья. Сортоиспытания проводятся на базе филиала КГУ — Курганской сельхозакадемии, где есть опытные поля, ботанический сад и плодово-овощной участок.', 3, 136, 1, 1, '2026-05-07 08:34:05');

