--
-- Структура таблицы `popular_humans`
--

CREATE TABLE `popular_humans` (
  `id` int NOT NULL,
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `last_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `patronymic` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `img` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `descr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `quote` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `date_born` date NOT NULL,
  `date_death` date DEFAULT NULL,
  `countries_id` int NOT NULL,
  `cities_id` int DEFAULT NULL,
  `user_id` int DEFAULT NULL,
  `moderation_status` int DEFAULT '0',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Дамп данных таблицы `popular_humans`
--

INSERT INTO `popular_humans` (`id`, `name`, `last_name`, `patronymic`, `img`, `type`, `descr`, `quote`, `date_born`, `date_death`, `countries_id`, `cities_id`, `user_id`, `moderation_status`, `created_at`) VALUES
(1, 'Пётр I', 'Романов', 'Алексеевич', 'petr1.jpg', 'Император', 'Пётр I — великий преобразователь и выдающийся государственный деятель, чья железная воля и стратегический гений превратили Россию в одну из ведущих мировых держав. Его правление стало эпохой грандиозного созидания: с нуля был построен мощный военно-морской флот, создана регулярная армия, одержана легендарная победа в Северной войне и основана новая блистательная столица — Санкт-Петербург. Обладая феноменальной работоспособностью и жаждой знаний, он лично освоил десятки ремесел, внедрил передовую науку и образование, открыл первые музеи и библиотеки, стремясь сделать свою страну просвещенной и сильной. Пётр I искренне жил интересами государства, заложив прочный фундамент отечественной промышленности и культуры, что позволило России на равных войти в круг великих европейских империй и на столетия вперед определить путь её развития.', 'А о Петре ведайте, что ему жизнь его не дорога, только бы жила Россия.', '1672-05-30', '1725-01-28', 1, 1, NULL, 1, '2026-05-03 22:50:54'),
(2, 'Екатерина II', 'Романова', 'Алексеевна', 'ekaterina2.jpg', 'Императрица', 'Екатерина II Великая — одна из самых ярких и успешных правительниц в истории России. Немецкая принцесса, сумевшая не только взойти на русский престол, но и стать truly русской душой и сердцем. Её правление называют «золотым веком» Российской империи: она провела грандиозную губернскую реформу, присоединила Крым и Новороссию, вела активную переписку с величайшими умами Европы, покровительствовала наукам и искусствам. При ней открылись первые институты для женщин, Эрмитаж начал собирать свою бесценную коллекцию, а Российская империя превратилась в могущественную европейскую державу, с которой считались все монархи мира.', 'Я желаю и хочу лишь блага той стране, в которую привел меня Господь; Он мне в том свидетель. Слава страны — моя собственная слава.', '1729-05-02', '1796-11-17', 1, NULL, NULL, 1, '2026-05-03 22:50:54'),
(3, 'Александр I', 'Романов', 'Павлович', 'aleksandr1.jpg', 'Император', 'Александр I — император-загадка, «благословенный» победитель Наполеона, чья эпоха стала временем великих надежд и разочарований. Воспитанный либералом Лагарпом, он вступил на престол с мечтами о конституции и свободе для России, но реальность самодержавного правления оказалась сложнее. Его величайшая заслуга — победа в Отечественной войне 1812 года и освобождение Европы от тирании Наполеона, что принесло ему немеркнущую славу. Он участвовал в Венском конгрессе, создавал Священный союз, даровал конституцию Польше и Финляндии, но так и не решился на коренные преобразования в России. Последние годы провёл в раздумьях и мистических исканиях, породив легенду о старце Фёдоре Кузьмиче — будто бы ушедшем от власти императоре.', 'Я остаюсь попрежнему в благих намерениях даровать России свободу и законы.', '1777-12-23', '1825-12-01', 1, 2, NULL, 1, '2026-05-03 22:50:54'),
(4, 'Николай I', 'Романов', 'Павлович', 'nikolay1.jpg', 'Император', 'Николай I — «рыцарь самодержавия», железный император, посвятивший своё правление укреплению незыблемости империи. Взойдя на престол под гром пушек на Сенатской площади, он сделал главной целью недопущение революции в России. Его эпоха стала временем высочайшего расцвета имперского могущества: кодификация законов, блестящие победы на Кавказе, подавление польского восстания и помощь европейским монархам в усмирении революций. При нём Россия достигла пика военно-политического влияния в Европе, став «жандармом Европы». Суровый, дисциплинированный и трудолюбивый, он искренне верил, что служит России, охраняя её от потрясений, но Крымская война показала хрупкость этой мощи и глубокий кризис николаевской системы.', 'Смеюсь, брат, над твоими конституционными мечтаниями.', '1796-07-06', '1855-03-02', 1, 2, NULL, 1, '2026-05-03 22:50:54'),
(5, 'Александр II', 'Романов', 'Николаевич', 'aleksandr2.jpg', 'Император', 'Александр II — царь-Освободитель, правитель, совершивший величайший социальный перелом в истории России. Осознавая гибельность крепостного права, он проявил политическую волю и отменил его в 1861 году, дав свободу миллионам крестьян. Это было лишь начало «Великих реформ»: он создал земства, ввёл новый суд — гласный и независимый, реформировал армию, ограничил цензуру и даровал университетам автономию. Россия при нём стремительно менялась, вставала на путь капиталистического развития, расширяла свои границы на Дальнем Востоке и в Средней Азии. Его трагическая гибель от бомбы народовольцев в день, когда он подписал проект конституции, стала символом того, как трудно даются России перемены.', 'Лучше отменить крепостное право сверху, нежели дожидаться, пока оно само собой начнет отменяться снизу.', '1818-04-29', '1881-03-13', 1, 1, NULL, 1, '2026-05-03 22:50:54'),
(6, 'Александр III', 'Романов', 'Александрович', 'aleksandr3.jpg', 'Император', 'Александр III — царь-Миротворец, мощная и цельная натура, символ стабильности и национальных устоев. За 13 лет его правления Россия не вела ни одной войны — уникальный случай в её истории, за что он и получил своё прозвище. Огромный физической силой и непоколебимый в убеждениях, он взял курс на укрепление самодержавия, «закручивание гаек» после реформ отца и поддержку русского национального начала. Он покровительствовал промышленности, строил Транссибирскую магистраль, при нём Россия достигла финансовой стабильности. Его знаменитая фраза «У России есть только два союзника: её армия и флот» стала крылатой и точно отражает его прагматичный и осторожный внешнеполитический курс.', 'Россия — для русских.', '1845-03-10', '1894-11-01', 1, 2, NULL, 1, '2026-05-03 22:50:54'),
(7, 'Николай II', 'Романов', 'Александрович', 'nikolay2.jpg', 'Император', 'Николай II — последний российский император, чья трагическая судьба стала отражением крушения великой империи. Глубоко верующий, семьянин и человек исключительного обаяния, он оказался на троне в эпоху тектонических сдвигов. Россия при нём пережила небывалый экономический подъём, стала мировым лидером по экспорту хлеба, расцвели науки и искусства, но нарастали и социальные противоречия. Он принял на себя тяжелейшие испытания: русско-японскую войну, революцию 1905 года, Первую мировую войну. Его решение отречься от престола в марте 1917 года стало точкой невозврата. Вместе с семьёй он принял мученическую кончину в подвале Ипатьевского дома, оставшись в истории как символ уходящей эпохи и объект ожесточённых споров.', 'Кругом измена, и трусость, и обман.', '1868-05-18', '1918-07-17', 1, 2, NULL, 1, '2026-05-03 22:50:54'),
(8, 'Георгий', 'Львов', 'Евгеньевич', 'lvov.jpg', 'Глава Временного правительства', 'Георгий Львов — представитель старинного княжеского рода, земский деятель и первый глава Временного правительства после Февральской революции. Человек безупречной репутации и искренний сторонник демократии, он пытался удержать страну от сползания в хаос в переломный момент истории. Его правительство провозгласило демократические свободы, отменило смертную казнь, подготовило Учредительное собрание, но оказалось бессильным перед растущей анархией и двоевластием. Не сумев совладать с революционной стихией и продолжив непопулярную войну, он ушёл в отставку, передав власть Керенскому. В истории остался как честный человек, оказавшийся не на своём месте в эпоху великих потрясений.', 'Революция неизбежно должна была привести к распаду государственной власти.', '1861-11-02', '1925-03-07', 1, NULL, NULL, 1, '2026-05-03 22:50:54'),
(9, 'Александр', 'Керенский', 'Фёдорович', 'kerensky.jpg', 'Глава Временного правительства', 'Александр Керенский — самая противоречивая фигура 1917 года, блестящий оратор и главная надежда русской демократии. Взлетев на гребне революционной волны, он стал министром юстиции, затем военным министром и, наконец, министром-председателем. Его пламенные речи собирали толпы, но он не смог остановить развал армии и нарастающий хаос. Женщины-«батальоны смерти», провозглашение республики, попытка подавить Корниловский мятеж — его действия были отчаянной попыткой спасти Россию от большевизма. Бежав из Зимнего дворца переодетым матросом, он провёл в эмиграции полвека, до конца дней пытаясь осмыслить свою роль в трагедии страны и оставив многотомные мемуары.', 'Бороться с большевизмом нужно не пулемётами, а социальной правдой.', '1881-05-04', '1970-06-11', 1, NULL, NULL, 1, '2026-05-03 22:50:54'),
(10, 'Владимир', 'Ленин', 'Ильич', 'lenin.jpg', 'Председатель Совнаркома', 'Владимир Ленин — создатель Советского государства, теоретик марксизма и одна из самых влиятельных фигур XX века. Гениальный стратег и безжалостный политик, он сумел захватить власть в октябре 1917 года и удержать её в невероятно трудных условиях Гражданской войны и разрухи. Его идеи о партии нового типа, диктатуре пролетариата и мировой революции перевернули Россию и полмира. НЭП стал его последним гениальным прозрением — попыткой спасти экономику от военного коммунизма. Уйдя из жизни в расцвете сил, он оставил после себя не только мавзолей на Красной площади, но и мощнейшее государство, которое почти век жило по заветам Ильича.', 'Учиться, учиться и еще раз учиться.', '1870-04-22', '1924-01-21', 2, NULL, NULL, 1, '2026-05-03 22:50:54'),
(11, 'Иосиф', 'Сталин', 'Виссарионович', 'stalin.jpg', 'Генеральный секретарь', 'Иосиф Сталин — «отец народов», человек, построивший из отсталой аграрной страны ядерную сверхдержаву, но заплативший за это чудовищную цену. Его эпоха стала временем индустриализации, коллективизации, культурной революции и одновременно — массовых репрессий, ГУЛАГа и страха. Под его руководством была одержана величайшая победа в истории — над нацизмом в Великой Отечественной войне. Жёсткий прагматик, он сумел расширить влияние СССР на полмира, создать социалистический лагерь и атомную бомбу. Его образ навсегда останется символом невероятного могущества и нечеловеческой жестокости, великой Победы и великой трагедии русского народа.', 'Жить стало лучше, товарищи. Жить стало веселее.', '1878-12-18', '1953-03-05', 2, NULL, NULL, 1, '2026-05-03 22:50:54'),
(12, 'Никита', 'Хрущёв', 'Сергеевич', 'hrushchev.jpg', 'Первый секретарь ЦК', 'Никита Хрущёв — самый неординарный советский лидер, разоблачивший культ личности Сталина и попытавшийся дать стране глоток свободы. Начав с «оттепели» — освобождения миллионов узников ГУЛАГа, ослабления цензуры и XX съезда с его знаменитым докладом — он затем потрясал ботинком по трибуне ООН и грозил «кузькиной матерью». Он запустил спутник и Гагарина, но и расстрелял рабочих в Новочеркасске. Он строил коммунизм к 1980 году, сажал кукурузу от Москвы до Заполярья и передал Крым Украине. Снятый заговорщиками в 1964 году, он остался в памяти как человек-эпоха, искренне веривший, что можно построить рай на земле, но натворивший немало ошибок.', 'Мы вам покажем кузькину мать!', '1894-04-15', '1971-09-11', 2, NULL, NULL, 1, '2026-05-03 22:50:54'),
(13, 'Леонид', 'Брежнев', 'Ильич', 'brezhnev.jpg', 'Генеральный секретарь', 'Леонид Брежнев — человек, олицетворяющий собой эпоху «застоя», время стабильности, дефицита и нарастающего кризиса. При нём СССР достиг пика военного могущества — ядерного паритета с США, строил БАМ и газопроводы, раздавал квартиры и наращивал нефтедоллары. Начав с попыток реформ, он быстро успокоился и погрузил страну в болото застоя, где главным принципом стало «не дёргаться». Эпоха Брежнева — это золотой век номенклатуры, пышные юбилеи, награды самому себе и полное отсутствие перемен. Уйдя в мир иной, он оставил страну в состоянии глубокого социально-экономического кризиса, который его преемникам было уже не остановить.', 'Наш курс — правильный курс.', '1906-12-19', '1982-11-10', 2, NULL, NULL, 1, '2026-05-03 22:50:54'),
(14, 'Юрий', 'Андропов', 'Владимирович', 'andropov.jpg', 'Генеральный секретарь', 'Юрий Андропов — самый загадочный советский лидер, руководитель КГБ, ставший генсеком с намерением навести в стране порядок. Умный, волевой и образованный, он понимал глубину кризиса и пытался дисциплинировать разваливающуюся империю. Его короткое правление запомнилось облавами в кинотеатрах и магазинах, проверками на рабочих местах и борьбой с коррупцией в высших эшелонах. Он начал массированную чистку партийных рядов и готовил серьёзные экономические реформы, но болезнь почек оборвала его жизнь. Успев показать лишь «твёрдую руку», он остался в народной памяти как надежда на наведение порядка, которой не суждено было сбыться.', 'Мы должны знать всё о врагах, думать о будущем нашей великой державы.', '1914-06-15', '1984-02-09', 2, NULL, NULL, 1, '2026-05-03 22:50:54'),
(15, 'Константин', 'Черненко', 'Устинович', 'chernenko.jpg', 'Генеральный секретарь', 'Константин Черненко — последний из «кремлёвских старцев», самый пожилой лидер СССР, чьё правление стало агонией брежневской системы. Человек больной и слабый, он пробыл у власти чуть больше года, став символом полного исчерпания возможностей прежнего курса. При нём ничего не менялось — страна замерла в ожидании перемен. Начал он с возвращения к брежневским порядкам и восстановления опальных соратников генсека, но быстро угас, уступив место Горбачёву. Его смерть, четвёртая за три года, уже почти не вызывала эмоций — все понимали, что так дальше жить нельзя и что эпоха похорон окончательно завершилась.', 'Мы будем неуклонно следовать курсом партии.', '1911-09-24', '1985-03-10', 2, NULL, NULL, 1, '2026-05-03 22:50:54'),
(16, 'Михаил', 'Горбачёв', 'Сергеевич', 'gorbachev.jpg', 'Президент', 'Михаил Горбачёв — первый и последний президент СССР, человек, запустивший перестройку и открывший страну миру. Начав с антиалкогольной кампании, ускорения и гласности, он быстро понял, что система требует кардинальных реформ. Он дал свободу слова, вернул из ссылки Сахарова, отпустил Восточную Европу и прекратил холодную войну, за что получил Нобелевскую премию мира. Но его половинчатые реформы, метания между рынком и социализмом привели к краху экономики и распаду великой державы. Оставшись без работы в декабре 1991 года, он до конца дней пытался объяснить, что его цель была спасти СССР, а не разрушить его, но история рассудила иначе.', 'Процесс пошел.', '1931-03-02', '2022-08-30', 2, NULL, NULL, 1, '2026-05-03 22:50:54'),
(17, 'Борис', 'Ельцин', 'Николаевич', 'yeltsin.jpg', 'Президент', 'Борис Ельцин — первый президент России, разрушитель советской системы и строитель новой государственности. Человек невероятной политической интуиции и воли, он бросил вызов Горбачёву, победил путч 1991 года и разогнал Верховный Совет в 1993-м. При нём Россия встала на путь рыночных реформ, обрела свою символику и конституцию. Его эпоха — это и свобода слова, и шоковая терапия, и ваучеры, и чеченская война, и дефолт 1998 года. Уставший и больной, он совершил, возможно, главный поступок — добровольно ушёл в отставку на пороге нового тысячелетия, передав власть Путину и попросив прощения у народа: «Я устал, я ухожу. Простите нас... Берегите Россию!»', 'Берегите Россию!', '1931-02-01', '2007-04-23', 3, NULL, NULL, 1, '2026-05-03 22:50:54'),
(18, 'Владимир', 'Путин', 'Владимирович', 'putin.jpg', 'Президент', 'Владимир Путин — центральная фигура современной российской и мировой политики, человек, определяющий судьбу России уже более двух десятилетий. Пришедший к власти на волне войны в Чечне и усталости от хаоса 90-х, он сделал ставку на стабильность, сильное государство и восстановление международного влияния. Его эпоха — это рост нефтедолларов, погашение долгов, наведение конституционного порядка, но и ужесточение внутренней политики, конфликты с Западом и возвращение Крыма. Воспринимаемый миллионами как гарант суверенитета и порядка, он сумел консолидировать власть и провести страну через череду кризисов, оставив открытым вопрос о будущем после себя.', 'Распад Советского Союза был крупнейшей геополитической катастрофой века.', '1952-10-07', NULL, 3, NULL, NULL, 1, '2026-05-03 22:50:54'),
(19, 'Дмитрий', 'Медведев', 'Анатольевич', 'medvedev.jpg', 'Заместитель председателя Совета безопасности Российской Федерации', 'Дмитрий Медведев — самый молодой президент в истории России, символ «тандема» и попытки модернизации страны. Пришедший на смену Путину в 2008 году, он провозгласил курс на свободу, модернизацию экономики и борьбу с правовым нигилизмом. Его президентство совпало с мировым кризисом и «перезагрузкой» отношений с Западом, но главным событием стала короткая пятидневная война с Грузией, после которой Россия признала независимость Абхазии и Южной Осетии. Уступив место обратно Путину в 2012 году, он остался в политике как премьер, а его знаменитая фраза о свободе стала символом несбывшихся надежд на либерализацию системы.', 'Свобода лучше, чем несвобода.', '1965-09-14', NULL, 3, NULL, NULL, 1, '2026-05-03 22:50:54'),
(38, 'Зиновий', 'Колобанов', 'Григорьевич', '1777832844_1.jpg', 'Командир танковой роты и танковый ас СССР', 'Зиновий Григорьевич Колобанов (25 декабря 1910 — 8 августа 1994) — советский танкист, старший лейтенант, прославившийся в годы Великой Отечественной войны: 20 августа 1941 года его экипаж на танке КВ‑1 за 30 минут уничтожил 22 немецких танка под Красногвардейском (ныне Гатчина). Участник Советско‑финской войны, награждён орденом Красного Знамени. В сентябре 1941‑го получил тяжёлое ранение, но после лечения вернулся в строй. Завершил военную службу в звании подполковника (уволен в запас в 1958 году), затем работал контролёром ОТК на Минском автозаводе, удостоен звания «Ударник коммунистического труда». Похоронен в Минске.', 'Экипаж танка — больше, чем семья. Ведь танк — машина, которая подчиняется коллективу. Здесь необходимы полная слаженность и взаимопонимание. Иначе воевать нельзя', '1910-12-25', '1994-08-08', 2, 9, 1, 1, '2026-05-03 22:50:54'),
(39, 'Гавриил', 'Илизаров', 'Абрамович', '1778129416_1.jpg', 'Советский хирург-ортопед и изобретатель', 'Гавриил Абрамович Илизаров — советский и российский хирург, создатель аппарата для лечения переломов и деформаций костей, который получил его имя. Его методы и аппараты позволили снизить инвалидизацию и экономические потери, связанные с травмами на производстве. В Кургане, где он работал, его имя стало символом медицинского гения. ', 'Кто ввёл в наш обиход это неприятное слово „проценты“? Надо, чтобы выздоравливал каждый!', '1921-06-15', '1992-07-24', 2, 136, 1, 1, '2026-05-07 07:50:16'),
(40, 'Марина', 'Доможирова', 'Фёдоровна', '1778130175_1.webp', 'Актриса театра и кино', 'Родилась 17 июня 1989 года в Кургане. С ранних лет проявляла интерес к сцене: участвовала в утренниках, школьных спектаклях и городских концертах. Первое обучение проходила в Челябинской государственной академии культуры и искусств, но вскоре перевелась в Санкт-Петербургский государственный университет на факультет искусств, где в 2010 году завершила обучение. Дебют на телеэкране состоялся в 2010 году в фильме «Исполнительный лист», где Доможирова сыграла эпизодическую роль блондинки. В том же году она появилась на экране в сериале «Литейный» в роли капитана милиции Алёны Зориной. ', '', '1989-06-17', NULL, 3, 136, 1, 1, '2026-05-07 08:02:55'),
(41, 'Вадим', 'Шумков', 'Михайлович', '1778130495_1.webp', 'Губернатор', 'Родился 9 марта 1971 года в селе Шастово Варгашинского района Курганской области. В 1996 году окончил Томский государственный университет по специальности «юриспруденция». Позже — Российскую академию государственной службы при президенте РФ, где получил квалификацию антикризисного управляющего.', 'Самый лучший коучинг для чиновников — \"дружеский направляющий пинок“, а не курсы и тренинги. Наиболее эффективной российской управленческой технологией остаётся переживший века пинок животворящий. На том стояла и стоять будет русская земля', '1971-03-09', NULL, 3, 136, 1, 1, '2026-05-07 08:08:15');

