--
-- Структура таблицы `users`
--

CREATE TABLE `users` (
  `id` int NOT NULL,
  `name` varchar(50) NOT NULL,
  `last_name` varchar(50) NOT NULL,
  `photo` varchar(256) DEFAULT NULL,
  `password` varchar(256) NOT NULL,
  `phone` varchar(20) NOT NULL,
  `email` varchar(256) NOT NULL,
  `role` int NOT NULL DEFAULT '0',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `ban_status` int NOT NULL DEFAULT '0',
  `ban_reason` text,
  `ban_until` datetime DEFAULT NULL,
  `violations_count` int NOT NULL DEFAULT '0'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

--
-- Дамп данных таблицы `users`
--

INSERT INTO `users` (`id`, `name`, `last_name`, `photo`, `password`, `phone`, `email`, `role`, `created_at`, `updated_at`, `ban_status`, `ban_reason`, `ban_until`, `violations_count`) VALUES
(1, 'Администратор', '  ', NULL, '$2y$10$0X8kfwx8yMB7vNg494TLaO/2Y8kwxfx28HuTTlVSPLnUrrHlDpR1O', '+7(963)868-01-07', 'Okulum@gmail.com', 1, '2026-05-05 13:06:04', '2026-05-12 10:44:20', 0, NULL, NULL, 1),
(3, 'Сократ', 'Артуров', '1777716291_PpwXb8vj8-.png', '$2y$13$kJcHMIFg0WwewDxuexKsCuMDUY52cATs79HGO9Skb5aRxO670eXFi', '+7(999)999-99-99', 'Vasja2.rudnih@gmail.com', 0, '2026-05-05 00:00:00', '2026-05-12 18:09:23', 0, NULL, NULL, 1);

