--
-- Структура таблицы `vehicles`
--

CREATE TABLE `vehicles` (
  `id` int NOT NULL,
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `img` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `descr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `countries_id` int NOT NULL,
  `cities_id` int DEFAULT NULL,
  `user_id` int DEFAULT NULL,
  `moderation_status` int DEFAULT '0',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Дамп данных таблицы `vehicles`
--

INSERT INTO `vehicles` (`id`, `name`, `img`, `descr`, `type`, `status`, `countries_id`, `cities_id`, `user_id`, `moderation_status`, `created_at`) VALUES
(2, 'Ледокол «Ермак»', 'veh1.webp', 'Построен в 1899 году в Ньюкасле по проекту адмирала С.О. Макарова. Первый в мире ледокол арктического класса мощностью 9000 л.с. Мог форсировать льды толщиной до 2 метров. Прослужил 64 года (до 1963 года), участвовал в спасении экспедиций Нобиле и парохода «Челюскин».', 'Гражданская', 'Музейный экспонат', 1, 2, NULL, 1, '2026-05-03 22:50:54'),
(4, 'Паровоз серии «О»', 'veh2.webp', 'Товарный паровоз с осевой формулой 0-3-0, выпускался с 1890 по 1928 год (более 9000 штук). Рабочее давление 12 атм, скорость до 55 км/ч. Именно «овечки» тянули эшелоны в Первую мировую и Гражданскую войны. Последний паровоз этой серии работал до 1972 года.', 'Гражданская', 'Музейный экспонат', 1, 23, NULL, 1, '2026-05-03 22:50:54'),
(5, 'Броненосец «Пётр Великий»', 'veh3.webp', 'Заложен в 1872 году, спущен на воду в 1877-м. Водоизмещение 10 000 тонн, броня 356 мм, скорость 14 узлов. Один из сильнейших броненосцев своего времени, первым в русском флоте получил башенные установки. В строю до 1959 года (как плавучая казарма).', 'Военная', 'Музейный экспонат', 1, 2, NULL, 1, '2026-05-03 22:50:54'),
(6, 'Первый русский автомобиль Фрезе и Яковлева', 'veh4.jpg', 'Создан в 1896 году Евгением Яковлевым (двигатель) и Петром Фрезе (шасси). Двигатель — 2 л.с., максимальная скорость — 21 км/ч. Продемонстрирован на Нижегородской выставке, но в серию не пошёл из-за отсутствия дорог. Тем не менее — первый русский серийный автомобиль (изготовлено 2 экземпляра).', 'Гражданская', 'Музейный экспонат', 1, 2, NULL, 1, '2026-05-03 22:50:54'),
(8, 'Теплоход «Вандал»', 'veh5.webp', 'Построен на Сормовском заводе в 1903 году — первый в мире теплоход с двигателем Дизеля (три дизеля мощностью по 120 л.с.). Совершал рейсы по Волге и Каспию. Был самым экономичным судном своего времени (расход топлива в 3 раза ниже паровых машин).', 'Гражданская', 'Музейный экспонат', 1, 23, NULL, 1, '2026-05-03 22:50:54'),
(9, 'Самолёт «Русский витязь»', 'veh6.webp', 'Создан Игорем Сикорским в 1913 году на Русско-Балтийском вагонном заводе. Первый в мире четырёхмоторный самолёт (4×100 л.с.). Размах крыла 28 м, взлётная масса 4 т. Совершил 53 успешных полёта, заложив основу для тяжёлой авиации. Разбит в 1913 году при падении двигателя.', 'Гражданская', 'Опытный образец', 1, 2, NULL, 1, '2026-05-03 22:50:54'),
(10, 'Бомбардировщик «Илья Муромец»', 'veh7.jpg', 'Первый в мире серийный четырёхдвигательный бомбардировщик-биплан. Создан российским авиаконструктором Игорем Сикорским на базе самолёта «Русский витязь» и построен под его руководством', 'Военная', 'Музейный экспонат', 1, 2, NULL, 1, '2026-05-03 22:50:54'),
(11, 'Танк Т-34', 'veh8.webp', 'Средний танк конструкции Михаила Кошкина, принят на вооружение в 1940 году. Броня 45 мм с рациональными углами наклона, дизель В-2 мощностью 500 л.с., скорость 55 км/ч. Выпущено 84 000 штук. Лучший танк Второй мировой войны, сочетавший манёвренность, броню и огневую мощь (76-мм пушка).', 'Военная', 'Музейный экспонат', 2, 20, NULL, 1, '2026-05-03 22:50:54'),
(13, 'Реактивная установка «Катюша» (БМ-13)', 'veh9.webp', 'Первая в мире реактивная система залпового огня, принята на вооружение в 1941 году. 16 направляющих для 132-мм реактивных снарядов М-13. Залп из 16 снарядов за 7–10 секунд накрывал площадь 100×100 м. Испытана 14 июля 1941 года под Оршей, наводила ужас на вермахт.', 'Военная', 'Музейный экспонат', 2, 1, NULL, 1, '2026-05-03 22:50:54'),
(14, 'Атомный ледокол «Ленин»', 'veh10.webp', 'Спущен на воду в 1957 году, первый в мире надводный корабль с ядерной энергоустановкой (реакторы ОК-150, затем ОК-900). Мощность 44 000 л.с., автономность 1 год без заправки. Проработал 32 года, прошёл более 650 000 морских миль, выведен из эксплуатации в 1989 году, теперь музей в Мурманске.', 'Гражданская', 'Музейный экспонат', 2, 2, NULL, 1, '2026-05-03 22:50:54'),
(17, 'Сверхзвуковой пассажирский Ту-144', 'veh11.webp', 'Разработан в ОКБ Туполева, совершил первый полёт 31 декабря 1968 года (на 2 месяца раньше «Конкорда»). Крейсерская скорость 2300 км/ч (М=2,15), дальность 6500 км. Совершал рейсы Москва — Алма-Ата. Снят с эксплуатации в 1978 году из-за аварии и экономической неэффективности (пассажировместимость 140 чел., расход топлива 80 т/час).', 'Гражданская', 'Списан', 2, 1, NULL, 1, '2026-05-03 22:50:54'),
(19, 'Многоразовый космический корабль «Буран»', 'veh12.jpg', 'Создан в НПО «Молния» под руководством Глеба Лозино-Лозинского. Совершил единственный полёт 15 ноября 1988 года в полностью автоматическом режиме (без экипажа на борту), в отличие от американского Space Shuttle, требующего пилотов. При посадке отклонился от ВПП всего на 3 метра. Программа закрыта в 1993 году.', 'Гражданская', 'Опытный образец', 2, 1, NULL, 1, '2026-05-03 22:50:54'),
(24, 'Гиперзвуковой комплекс «Кинжал» (Х-47М2)', 'veh13.jpg', 'Аэробаллистическая ракета, разработана Корпорацией «Тактическое ракетное вооружение». Носитель — МиГ-31К. Скорость М=10–12, дальность до 2000 км, боевая часть до 500 кг. Манёвр на гиперзвуке делает её неуязвимой для любых существующих систем ПВО (Patriot, SAMP-T, THAAD). Принята на вооружение в 2017 году.', 'Военная', 'В строю', 3, 1, NULL, 1, '2026-05-03 22:50:54'),
(26, 'Атомный ледокол проекта 22220 («Арктика»)', 'veh14.webp', 'Головной ледокол серии (заложен в 2013 году, спущен в 2020-м). Мощность 60 МВт на валах (самый мощный в мире), способен преодолевать льды толщиной 2,8 м, длина 173 м, водоизмещение 33 500 тонн. Уникальная двухосадочная конструкция (9 м в реках, 10,5 м в море) позволяет работать и в устьях сибирских рек, и на Северном морском пути.', 'Гражданская', 'В строю', 3, 2, NULL, 1, '2026-05-03 22:50:54'),
(27, 'Магистральный самолёт МС-21-310', 'veh15.jpg', 'Разработан ПАО «Яковлев» (бывш. Иркут). Первый полёт в 2017 году. Пассажировместимость 163–211 чел., дальность 6000 км. Ключевая инновация — композитное крыло из российских материалов (PU-1500), на 15% легче алюминиевого. Оснащён двигателями ПД-14 (российская разработка). Замена Boeing 737 и Airbus A320.', 'Гражданская', 'В строю', 3, 37, NULL, 1, '2026-05-03 22:50:54'),
(31, 'Крейсер «Варяг»', 'veh16.webp', 'Бронепалубный крейсер 1-го ранга, построен в 1899 году в Филадельфии. Героически сражался у Чемульпо в 1904 году против японской эскадры. После боя был затоплен экипажем, не спустив флага. В 1905 году поднят японцами, служил под именем «Сойя», в 1916 году выкуплен Россией.', 'Военная', 'Музейный экспонат', 1, NULL, NULL, 1, '2026-05-03 22:50:54'),
(32, 'Подводная лодка «Дельфин»', 'veh17.webp', 'Первая боевая подводная лодка русского флота, спущена на воду в 1903 году. Водоизмещение 113 тонн, скорость 9 узлов, вооружение — 2 торпедных аппарата. Участвовала в Русско-японской войне. Прообраз всех русских подводных сил.', 'Военная', 'Музейный экспонат', 1, 2, NULL, 1, '2026-05-03 22:50:54'),
(33, 'Тяжёлый танк ИС-3', 'veh18.webp', 'Разработан в 1944 году под руководством Ж. Котина. Броня 120 мм с рациональными углами наклона, пушка 122 мм, масса 46 тонн. Участвовал в Параде Победы в Берлине в 1945 году, поразил союзников своей «щучей» носовой частью. Состоял на вооружении до 1990-х.', 'Военная', 'Музейный экспонат', 2, 33, NULL, 1, '2026-05-03 22:50:54'),
(34, 'Вертолёт Ми-24', 'veh19.webp', 'Боевой вертолёт-транспортёр, разработан в ОКБ Миля, первый полёт в 1969 году. Скорость до 335 км/ч, вооружение — пушка, ракеты, ПТУР. Участвовал в Афганистане (где получил прозвище «Крокодил»), Чечне, Сирии. Состоит на вооружении более чем в 30 странах.', 'Военная', 'В строю', 2, 1, NULL, 1, '2026-05-03 22:50:54'),
(35, 'Танк Т-14 «Армата»', 'veh20.webp', 'Новейший российский танк на универсальной гусеничной платформе «Армата». Представлен в 2015 году. Необитаемая башня, экипаж 3 человека в изолированной бронекапсуле. 125-мм пушка 2А82-1М, активная защита «Афганит». Серийно не поставлялся в войска (статус — опытный).', 'Военная', 'Опытный образец', 3, NULL, NULL, 1, '2026-05-03 22:50:54'),
(36, 'Электромобиль «Кама-1»', 'veh21.jpg', 'Первый российский серийный электромобиль, представлен КАМАЗом в 2021 году. Запас хода 250 км, батарея 33 кВт·ч, максимальная скорость 120 км/ч. Используется для городских перевозок и коммунальных служб. Выпущено около 100 штук.', 'Гражданская', 'В строю', 3, 2, NULL, 1, '2026-05-03 22:50:54'),
(38, 'БРЭМ-Л', '1778130781_1.webp', 'бронированная ремонтно-эвакуационная машина, разработанная на базе боевой машины пехоты БМП-3 на Курганмашзаводе. Предназначена для эвакуации застрявшей и повреждённой лёгкой техники, в том числе из-под огня противника. Обеспечивает необходимый ремонт и техническое обслуживание в полевых условиях.', 'Военная', 'В строю', 3, 136, 1, 1, '2026-05-07 08:13:01'),
(39, '«Курганец-25»', '1778130970_1.webp', 'универсальное модульное шасси, на базе которого создаются различные машины, включая БМП и БТР. Опытная модель впервые прошла по Красной площади в 2015 году. В 2023 году «Курганмашзавод» сообщил, что БМП получила обновлённое и доработанное шасси. \r\nПо информации на май 2025 года, «Курганец-25» продолжает проходить предварительные испытания.', 'Военная', 'Опытный образец', 3, 136, 1, 1, '2026-05-07 08:16:10'),
(40, 'МКСМ-1000', '1778131092_1.jpg', 'Колёсная машина с бортовым поворотом, предназначенная для строительных, коммунальных и сельскохозяйственных работ. Грузоподъёмность составляет 800 и 1000 кг соответственно. На неё устанавливаются дизельные двигатели Hatz 3M41.', 'Гражданская', 'В строю', 3, 136, 1, 1, '2026-05-07 08:18:12'),
(41, 'ТМ-140', '1778131193_1.jpg', 'Гусеничный плавающий вездеход, который применяется для работы в условиях Крайнего Севера. Машина разработана конструкторским бюро «Курганмашзавода» и выпускается этим предприятием, входящим в холдинг «Высокоточные комплексы» госкорпорации «Ростех».', 'Гражданская', 'В строю', 3, 136, 1, 1, '2026-05-07 08:19:53');

-- --------------------------------------------------------

--
-- Структура таблицы `weapons`
--

CREATE TABLE `weapons` (
  `id` int NOT NULL,
  `name` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `img` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `descr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `countries_id` int NOT NULL,
  `cities_id` int DEFAULT NULL,
  `user_id` int DEFAULT NULL,
  `moderation_status` int DEFAULT '0',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Дамп данных таблицы `weapons`
--

INSERT INTO `weapons` (`id`, `name`, `img`, `descr`, `status`, `countries_id`, `cities_id`, `user_id`, `moderation_status`, `created_at`) VALUES
(1, 'Трёхлинейная винтовка Мосина обр. 1891 г.', 'weapon1.webp', 'Основная магазинная винтовка Русской императорской армии. Калибр 7,62 мм (3 линии), магазин на 5 патронов, дальность стрельбы до 2000 м. Отличалась исключительной надёжностью в любых условиях. За 1891–1917 годы выпущено более 3,7 млн единиц. Снайперский вариант стал грозой для немецких офицеров в ВОВ.', 'Снята с вооружения', 1, 124, NULL, 1, '2026-05-03 22:50:54'),
(2, 'Револьвер системы Нагана обр. 1895 г.', 'weapon2.jpg', 'Семизарядный револьвер, принятый на вооружение Русской армии в 1895 году. Калибр 7,62×38 мм. Уникальная особенность — обтюрация (при выстреле гильза входила в ствол, исключая прорыв газов). Состоял на вооружении офицеров, полиции, а затем и Красной армии. Выпускался до 1945 года. Символ русской революции и Гражданской войны.', 'Снят с вооружения', 1, NULL, NULL, 1, '2026-05-03 22:50:54'),
(3, 'Шашка казачья обр. 1881 г.', 'weapon3.jpg', 'Холодное оружие казачьих войск. Клинок длиной 85–90 см, слабо изогнутый, с односторонней заточкой. Носилась лезвием вверх. Отличалась удобством в рубящем ударе с коня. Состояла на вооружении донских, кубанских, терских казаков до 1917 года. Символ русского казачества.', 'Снята с вооружения', 1, 123, NULL, 1, '2026-05-03 22:50:54'),
(4, 'Кинжал бебут (кавказский)', 'weapon4.jpg', 'Кинжал кавказского типа, принятый на вооружение в 1907 году. Клинок обоюдоострый, длиной 40–50 см. Состоял на вооружении артиллеристов (взамен шашек), казаков и офицеров кавказских частей. Использовался как боевое и хозяйственное оружие.', 'Снят с вооружения', 1, 124, NULL, 1, '2026-05-03 22:50:54'),
(5, 'Пистолет-пулемёт Фёдорова обр. 1916 г.', 'weapon5.jpg', 'Первый в мире автомат под промежуточный патрон (японский 6,5 мм). Магазин на 25 патронов, вёлся одиночный и автоматический огонь. Выпущено около 3200 штук. Использовался в Первую мировую, Гражданскую и советско-финскую войну. Опередил своё время на 30 лет.', 'Снят с вооружения', 1, NULL, NULL, 1, '2026-05-03 22:50:54'),
(6, 'Пистолет-пулемёт ППШ-41', 'weapon6.jpeg', 'Самый массовый автомат Красной армии в ВОВ. Калибр 7,62×25 мм ТТ, темп стрельбы 900 выстр./мин. Магазин на 71 патрон (дисковый). Выпущено около 6 млн штук. Немцы охотно использовали трофейные ППШ. «Оружие Победы».', 'Снят с вооружения', 2, 1, NULL, 1, '2026-05-03 22:50:54'),
(7, 'Пистолет-пулемёт ППС-43', 'weapon7.jpg', 'ППС Судаева для десантников и разведчиков. Вес 3,7 кг (легче ППШ на 1,5 кг), магазин на 35 патронов. Выпущено около 2 млн штук. Компактный, надёжный, технологичный. Вершина советских ПП периода войны.', 'Снят с вооружения', 2, 2, NULL, 1, '2026-05-03 22:50:54'),
(8, 'Автомат Калашникова АК-47', 'weapon8.webp', 'Самый массовый автомат в истории (более 100 млн). Калибр 7,62×39 мм, магазин на 30 патронов. Простота и колоссальная надёжность. Состоит на вооружении 50 стран. Символ советского оружия.', 'Состоит на вооружении (частично)', 2, 124, NULL, 1, '2026-05-03 22:50:54'),
(9, 'Снайперская винтовка Драгунова СВД', 'weapon9.jpg', 'Самозарядная снайперская винтовка. Калибр 7,62×54 мм R, магазин на 10 патронов. Прицельная дальность 1300 м. Одна из лучших снайперских винтовок в мире. Выпущено более 1,5 млн.', 'Состоит на вооружении', 2, 124, NULL, 1, '2026-05-03 22:50:54'),
(10, 'Пистолет Макарова ПМ', 'weapon10.jpg', 'Основной армейский пистолет СССР и России с 1951 года. Калибр 9×18 мм, магазин на 8 патронов. Простой, надёжный, дешёвый в производстве. Выпущено более 5 млн. Состоит на вооружении до сих пор.', 'Состоит на вооружении', 2, 124, NULL, 1, '2026-05-03 22:50:54'),
(11, 'Нож разведчика НР-40', 'weapon11.webp', 'Штатный нож разведчиков Красной армии в ВОВ. Клинок 152 мм из стали У7. Мог перерезать проволочные заграждения. Носился в кожаных ножнах. Символ советского разведчика.', 'Снят с вооружения', 2, 23, NULL, 1, '2026-05-03 22:50:54'),
(12, 'Финка НКВД обр. 1940 г.', 'weapon12.jpg', 'Финский нож сотрудников НКВД. Клинок 125 мм, рукоять из капа. Отличие от гражданских — дужка (крестовина) и клеймо завода. Символ советских органов госбезопасности.', 'Снята с вооружения', 2, 23, NULL, 1, '2026-05-03 22:50:54'),
(13, 'Автомат Никонова АН-94 «Абакан»', 'weapon13.jpg', 'Автомат со смещённым импульсом отдачи. При стрельбе очередью из 2 патронов они вылетают до того, как отдача достигает плеча. Кучность в 2–3 раза выше АК-74. Выпущено около 10 тыс. Состоит на вооружении спецподразделений.', 'Состоит на вооружении (ограниченно)', 3, 124, NULL, 1, '2026-05-03 22:50:54'),
(14, 'Пистолет Ярыгина ПЯ «Грач»', 'weapon14.webp', 'Основной армейский пистолет РФ с 2003 года. Калибр 9×19 мм, магазин на 18 патронов. Пришёл на смену ПМ. Надёжен, мощный, большая ёмкость магазина.', 'Состоит на вооружении', 3, 124, NULL, 1, '2026-05-03 22:50:54'),
(15, 'Винтовка снайперская Чукавина СВЧ', 'weapon15.jpg', 'Новая снайперская винтовка на смену СВД. Калибр 7,62×54 мм R, магазин на 10–20 патронов. Легче СВД на 0,5 кг. Модульная, планки Пикатинни. Поступает в войска с 2024 года.', 'Состоит на вооружении', 3, 124, NULL, 1, '2026-05-03 22:50:54'),
(16, 'Нож разведчика стреляющий НРС-2', 'weapon16.jpg', 'Нож со встроенным стреляющим механизмом (2 патрона СП-4 калибра 7,62×42 мм). Дальность стрельбы до 25 м. Состоит на вооружении спецназа ГРУ, ВДВ, ФСБ.', 'Состоит на вооружении', 3, 123, NULL, 1, '2026-05-03 22:50:54'),
(17, 'Кинжал «Каратель»', 'weapon17.webp', 'Боевой нож спецподразделений ФСБ. Клинок 180 мм, обоюдоострый, из стали 50Х14МФ. Отличная балансировка. Состоит на вооружении «Альфы», «Вымпела», ГРУ.', 'Состоит на вооружении', 3, 24, NULL, 1, '2026-05-03 22:50:54'),
(18, 'Автомат Калашникова АК-12', 'weapon18.jpg', 'Современная модификация АК, принята на вооружение в 2018 году. Калибр 5,45×39 мм. Планки Пикатинни, регулируемый приклад, улучшенная эргономика. Основной автомат ВС РФ.', 'Состоит на вооружении', 3, 124, NULL, 1, '2026-05-03 22:50:54'),
(19, 'Кортик морской офицерский обр. 1945 г.', 'weapon19.jpg', 'Парадное холодное оружие офицеров ВМФ СССР и РФ. Клинок четырёхгранный, длиной 240 мм. Носится на поясном ремне. Символ морских традиций.', 'Состоит на вооружении (парадное)', 3, 23, NULL, 1, '2026-05-03 22:50:54'),
(20, 'Пистолет Лебедева ПЛ-14', 'weapon20.jpg', 'Новый армейский пистолет на замену ПЯ. Калибр 9×19 мм, магазин на 16 патронов. Эргономичный, лёгкий (0,8 кг). Принят на вооружение в 2024 году.', 'Состоит на вооружении', 3, 124, NULL, 1, '2026-05-03 22:50:54');

